/*
    One facilitator guide per placement
    Generated from the Frontier Accelerator content workbook by generate.py.
    Do not hand-edit. Re-runnable: every statement is an ExternalId-keyed MERGE, nothing is deleted.
    Merged from three sheets: Preparation supplies the intro and checklist, Explore_Practice the in-flight guidance, Commit the close.
*/
SET NOCOUNT ON;
SET XACT_ABORT ON;
DECLARE @unresolved INT;
BEGIN TRANSACTION;

;WITH raw AS (
    SELECT * FROM (VALUES
        (N'FG-AE-ORIENT', N'WF-ORIENT-01', N'AE-ORIENT', N'This session sets the operating model for the AE path. The point is not tool fluency for its own sake; it is better account, pipeline, deal, and customer-conversation execution with human judgment visible.', N'The huddle is workflow-first. Every session uses real AE work, a practical AI-supported practice, and a human checkpoint. AI can assemble evidence, summarize, draft, and monitor; the AE owns judgment, customer trust, commitments, and next decisions.', N'Which part of your week is assembling information rather than deciding anything?
Where do you already use AI, and where have you avoided it?
What would you need to see before you trusted an AI-drafted account, pipeline, or customer-facing output?', N'Before the session: confirm access to the tools named for this path, and come ready to describe the work you repeat most weeks. No prior AI experience is needed for this session.', N'Which account, pipeline, or customer-facing work do you repeat every week without thinking of it as a workflow?
Which of those steps is assembling information rather than making a decision?
Where must the AE judgment stay human no matter how good the output gets?', N'Listen for unvoiced scepticism, access blockers stated as disinterest, the assumption that this is a tool rollout, and people who describe only their exceptional work rather than the work they repeat. The recurring, unglamorous tasks are the ones worth mapping.', N'Move from how the motion works to the recurring work each person will map with the discovery prompt this week.', N'If tool access is not confirmed, still run the discovery conversation and record access blockers separately from interest. The discovery prompt can be run in whichever tool the person already has.', N'Close by pointing the team to the resources for next week''s topic and to the workflow-discovery prompt below. Week 1 is for finding the recurring work worth automating.', N'Which part of your week had you never thought of as a workflow until now? What would have to be true before you trusted AI with it?', N'Run this in Microsoft 365 Copilot, Cowork, or Scout before the next huddle, then bring the result to the session:

"I am an Account Executive at Microsoft and I want to find the recurring work in my week that AI could take on.
1. First, look at my calendar, mail and Teams activity from the last four weeks and tell me what you can see about where my time actually goes. If you cannot access that data, say so and move to step 2 rather than guessing.
2. Then ask me up to five short questions, one at a time, to cover the work that never shows up in a calendar or an inbox.
3. Then list the five things I do most often. For each one give an estimate of the time it costs me per month, whether it is best handled as a saved prompt, a reusable skill, a scheduled automation or an existing agent, and the one judgment that must stay mine.
4. Rank them by time returned and tell me which one to start with."', N'Bring the ranked list of the five things you repeat most, which of them looked like a prompt, skill, automation, or agent fit, and any AI experience from the week, including anything that did not work.'),
        (N'FG-AE-PLAN', N'WF-X-PLAN-01', N'AE-PLAN', N'Account planning fails when it becomes an inventory. Today is about a short operating plan that helps you decide where attention goes this week.', N'Prioritization requires saying no. AI can assemble customer, pipeline, renewal, whitespace, partner, and investment signals. The AE decides which account deserves action and why.', N'Which accounts get your attention by habit rather than evidence? Where is the account plan missing a decision? What signal would change your priority list?', N'Before the session: bring one territory or account list and one account where the next action is unclear.', N'Which account deserves attention that it is not getting? Which account gets attention mostly by habit? What evidence would change your top three?', N'Listen for planning as annual documentation, prioritization by revenue alone, unclear next actions, missing role coverage, and customer priorities not connected to pipeline.', N'Move from account list discussion to one AE selecting a top account and naming the next action.', N'If tools are unavailable, run the prioritization manually and record the prompt or Scout/Cowork skill candidate for later.', N'Name the top accounts you will act on and the evidence behind the priority.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Use AI to build or refine one account priority view, then choose one next action you will actually take.', N'Bring the prioritized account list, source signals, the action chosen, and any assumptions you rejected.'),
        (N'FG-AE-PIPE-1', N'WF-X-PIPE-01', N'AE-PIPE-1', N'Today is about restoring trust in the pipeline signal before it becomes a forecast argument.', N'Bad data creates bad inspection. Stage, close date, next step, customer engagement, and partner attach should reflect reality. AI can flag issues; the AE verifies and decides the correction.', N'Where does your pipeline data most often mislead you? Which field do you trust least? Which opportunity would you hesitate to defend in a review?', N'Before the session: bring the scope you normally inspect for pipeline reviews and one opportunity you suspect may be stale or misrepresented.', N'Which opportunity would you not want inspected right now? What field, date, or next step might be telling the wrong story? What correction would change the forecast conversation?', N'Listen for manual reconciliation, stale dates, close-date optimism, missing customer engagement, and records corrected only right before reviews.', N'Move from aggregate gap to one opportunity that needs correction or verification.', N'If certified reports are unavailable, map the inspection routine and identify where evidence should come from.', N'Name one opportunity record to correct, verify, or escalate for missing evidence.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Run one pipeline signal-quality check and correct or flag one material issue.', N'Bring the before/after record state or issue list, the source signal, and the decision you made as the owner.'),
        (N'FG-AE-PIPE-2', N'WF-X-PIPE-01', N'AE-PIPE-2', N'A forecast narrative explains what changed, what is at risk, and what decision is needed. Today is about building that story from evidence.', N'The number alone does not create confidence. Movement, risk, timing, and inspection questions need to be visible. AI can draft the story, but the AE owns the commitment and caveats.', N'What changed since the last review? Which commit has the weakest evidence? What question from your manager would be hardest to answer?', N'Before the session: bring the current forecast scope and the report or meeting notes you use for weekly inspection.', N'What changed since last week? Which commit carries the most risk? What would your manager ask that the current narrative cannot answer?', N'Listen for forecast narrative built from memory, risk without evidence, unclear inspection questions, and confusion between confidence and wishful thinking.', N'Move from report output to the narrative the AE would actually use in a forecast review.', N'If data access is unavailable, build the narrative structure and mark which claims need certified data.', N'Name one forecast risk and the inspection question that will resolve it.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Draft one forecast narrative for your scope and use it in your next inspection or manager discussion.', N'Bring the narrative, supporting metrics, unresolved questions, and what you changed after human review.'),
        (N'FG-AE-OPP', N'WF-X-OPP-01', N'AE-OPP', N'The next opportunity is often already visible in customer signals. Today is about finding and testing those signals without creating pipeline noise.', N'Whitespace is not just a product gap. A qualified opportunity has a trigger, stakeholder, business problem, next action, and evidence. AI can surface signals; the AE tests whether they are real.', N'Where did your last real opportunity come from? What makes a signal qualified rather than hopeful? Where might you be missing a signal because it sits outside MSX?', N'Before the session: bring one account with recent meetings, engagement, or whitespace that might become an opportunity.', N'Which signal looks promising but not yet qualified? What evidence would make it real? What customer action would test the hypothesis?', N'Listen for opportunities created to fill coverage, whitespace treated as product absence, duplicate opportunities, and signals without a named stakeholder or trigger.', N'Move from signal discovery to one opportunity hypothesis and the first outreach or discovery action.', N'If tooling is unavailable, work from one account’s known context and draft the prompt to run later.', N'Commit to to testing one opportunity signal with a real customer or account-team action.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Qualify one opportunity hypothesis and document the trigger, evidence, next action, and uncertainty.', N'Bring the opportunity hypothesis, evidence, outreach or discovery step, and whether it became qualified or was rejected.'),
        (N'FG-AE-CONV', N'WF-X-CONV-01', N'AE-CONV', N'Customer conversations are where decisions move. Today is about preparing the position, evidence, objections, and ask before the meeting starts.', N'A brief is not a recap. It should state the intended outcome, customer context, evidence, open questions, likely objections, and the ask. The AE validates tone and relationship nuance.', N'What do you often walk into a meeting still not knowing? What would change if the ask were explicit before the meeting? Which claim would need validation before customer use?', N'Before the session: bring one upcoming customer meeting, the desired decision, and any approved source materials you want to use.', N'What decision should the meeting move? What claim must be validated? What objection is likely but uncomfortable to prepare for?', N'Listen for recaps instead of positions, meetings with no intended outcome, generic value language, unsupported claims, and missing fallback asks.', N'Move from preparation concept to one live meeting brief and the ask the AE will use.', N'If tools are unavailable, build the brief skeleton manually and identify source gaps.', N'Pick one customer meeting and names the primary ask and fallback ask.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Prepare one customer conversation brief and validate the claims before use.', N'Bring the brief, source signals, validated or removed claims, primary ask, fallback ask, and meeting outcome if available.'),
        (N'FG-AE-DEAL', N'WF-X-DEAL-01', N'AE-DEAL', N'Strategic deals stall when the next decision, blocker, or owner is unnamed. Today is about making the deal inspectable.', N'A close date is not a plan. Exit criteria, approvals, commercial dependencies, stakeholder coverage, and customer actions determine whether the deal can move. AI can organize the deal picture; the AE routes decisions to the right owners.', N'What is your deal really waiting on? Which approval, customer action, or role gap is not yet explicit? What should not be decided by AI?', N'Before the session: bring one live opportunity, the current stage, and the next decision you believe is needed.', N'What is the next decision, not the next task? Which blocker has no owner? Which commercial, technical, or partner decision needs another role?', N'Listen for close date as proxy for plan, approval paths discovered late, role gaps, unsupported deal assumptions, and AI outputs that overstep CE or SME authority.', N'Move from deal summary to the next decision and owner map.', N'If systems are unavailable, whiteboard the decision path, blockers, and accountable owners.', N'Name the next decision on one live deal and the owner for every blocker.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Inspect one strategic deal and route at least one blocker or decision to the right owner.', N'Bring the deal inspection, blocker-owner map, routed ask, and what changed in the deal plan.'),
        (N'FG-AE-RENEW', N'WF-X-RENEW-01', N'AE-RENEW', N'Renewal risk is usually visible before the renewal conversation. Today is about finding it while there is still time to act.', N'Renewal health depends on value evidence, usage or consumption signals, relationship recency, commercial readiness, and expansion logic. AI can surface patterns; the AE validates intent and next action.', N'Which upcoming renewal has the weakest value evidence? What expansion hypothesis is already visible? Where do you need CSAM, CSA, CE, or SSP input?', N'Before the session: bring one account renewing in the next planning window and the evidence you currently use to judge risk.', N'What is the largest renewal risk? What value evidence would the customer recognize? Which expansion signal is supported by usage, consumption, or customer priority?', N'Listen for renewals treated as admin, value evidence built too late, expansion detached from customer outcomes, and unclear CSAM/CSA/CE ownership.', N'Move from renewal principles to one account and the action that changes risk this week.', N'If data is unavailable, work from known context and list evidence gaps to close.', N'Name one renewal risk, one value evidence gap, and one expansion hypothesis.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Assess one upcoming renewal and take one action that reduces risk or strengthens value evidence.', N'Bring the renewal assessment, risk, evidence gap, expansion hypothesis, and the owner for the next action.'),
        (N'FG-ATS-ORIENT', N'WF-ORIENT-01', N'ATS-ORIENT', N'This session explains how the huddle motion works and how ATS team members should test AI on real technical strategy work.', N'Huddles are workflow-led, not tool demos. Every session ends with one experiment. Human judgment stays explicit.', N'Which part of your week is assembling information rather than deciding anything?
Where do you already use AI, and where have you avoided it?
What would you need to see before you trusted an AI-drafted technical strategy output?', N'Before the session: confirm access to the tools named for this path, and come ready to describe the work you repeat most weeks. No prior AI experience is needed for this session.', N'Which technical strategy work do you repeat every week without thinking of it as a workflow?
Which of those steps is assembling information rather than making a decision?
Where must the ATS judgment stay human no matter how good the output gets?', N'Listen for unvoiced scepticism, access blockers stated as disinterest, the assumption that this is a tool rollout, and people who describe only their exceptional work rather than the work they repeat. The recurring, unglamorous tasks are the ones worth mapping.', N'Move from how the motion works to the recurring work each person will map with the discovery prompt this week.', N'If tool access is not confirmed, still run the discovery conversation and record access blockers separately from interest. The discovery prompt can be run in whichever tool the person already has.', N'Close by pointing the team to the resources for next week''s topic and to the workflow-discovery prompt below. Week 1 is for finding the recurring work worth automating.', N'Which part of your week had you never thought of as a workflow until now? What would have to be true before you trusted AI with it?', N'Run this in Microsoft 365 Copilot, Cowork, or Scout before the next huddle, then bring the result to the session:

"I am an Account Technology Strategist at Microsoft and I want to find the recurring work in my week that AI could take on.
1. First, look at my calendar, mail and Teams activity from the last four weeks and tell me what you can see about where my time actually goes. If you cannot access that data, say so and move to step 2 rather than guessing.
2. Then ask me up to five short questions, one at a time, to cover the work that never shows up in a calendar or an inbox.
3. Then list the five things I do most often. For each one give an estimate of the time it costs me per month, whether it is best handled as a saved prompt, a reusable skill, a scheduled automation or an existing agent, and the one judgment that must stay mine.
4. Rank them by time returned and tell me which one to start with."', N'Bring the ranked list of the five things you repeat most, which of them looked like a prompt, skill, automation, or agent fit, and any AI experience from the week, including anything that did not work.'),
        (N'FG-ATS-INTEL', N'WF-X-PLAN-01', N'ATS-INTEL', N'Today is about build an account intelligence and meeting prep brief without turning the huddle into a tool demo or a status review.', N'The goal is An account intelligence brief with technical risks, workload signals, stakeholder context, and next actions. AI can assemble evidence and draft options, but ATS judgment stays accountable for strategy, technical accuracy, and next decisions.', N'Which account are you least confident you could brief someone on right now?
Where does your current account picture come from, and how old is it?
What technical signal would change your priorities this week if you knew it today?', N'Before the session: confirm access to the named tools, bring one real account or technical strategy example, and review the commitment from the prior huddle.', N'What is in your account brief that you could not source if challenged?
Which signal in the brief actually changes what you do next week?
What is missing that you only notice once it is written down?', N'Listen for briefs assembled from memory rather than systems, KPI figures quoted without their definition or date, technical risks with no named owner, and stakeholder context that is a year old. Also listen for the brief becoming an end in itself rather than driving a decision.', N'Move from the assembled account picture to the single signal that should change this week''s priorities.', N'If tooling is unavailable, map the workflow and human checkpoint manually, then draft the prompt for later testing.', N'Name the account you will brief, the signal you will chase down, and the source you will use to close it. If the brief will not change a decision, pick a different account.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Build an account intelligence brief for one account, and chase down the one signal you could not source.', N'Bring the brief and the signal you had to verify manually.'),
        (N'FG-ATS-NARR', N'WF-X-CONV-01', N'ATS-NARR', N'Today is about assemble an executive technical customer narrative without turning the huddle into a tool demo or a status review.', N'The goal is An executive-ready technical narrative with sourced claims, proof points, decision questions, and a technical ask. AI can assemble evidence and draft options, but ATS judgment stays accountable for strategy, technical accuracy, and next decisions.', N'When did an executive last stop you to ask what something meant?
Which part of your technical story do you find hardest to say without jargon?
What decision do you actually need from the executive, and have you ever asked for it directly?', N'Before the session: confirm access to the named tools, bring one real account or technical strategy example, and review the commitment from the prior huddle.', N'Read your opening line aloud. Would a CFO know what you meant?
Which claim in your narrative rests on a proof point you do not have?
What are you asking the executive to decide, stated in one sentence?', N'Listen for architecture described rather than translated, value asserted without evidence, narratives that end without an ask, and jargon that survived because nobody in the room questioned it. Also listen for a narrative aimed at the technical stakeholder while claiming to target the executive.', N'Move from the technical story to the one decision you want the executive to make, and the proof they need to make it.', N'If tooling is unavailable, map the workflow and human checkpoint manually, then draft the prompt for later testing.', N'Name the executive audience, the single decision you will ask for, and the proof point they still need. If there is no ask, the narrative is not ready.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Rewrite one technical narrative for an executive audience, and state the single decision you are asking for.', N'Bring the narrative, the ask, and the proof point you still need.'),
        (N'FG-ATS-WORKLOAD', N'WF-X-PLAN-01', N'ATS-WORKLOAD', N'Today is about prioritize ai and azure workloads by readiness and impact without turning the huddle into a tool demo or a status review.', N'The goal is A ranked workload view with readiness, impact, evidence, owner, and validation gaps. AI can assemble evidence and draft options, but ATS judgment stays accountable for strategy, technical accuracy, and next decisions.', N'Which workload are you spending time on because it is genuinely the priority, and which because it has momentum?
What readiness evidence would change your ranking?
Which workload would you drop if you had to drop one this quarter?', N'Before the session: confirm access to the named tools, bring one real account or technical strategy example, and review the commitment from the prior huddle.', N'What evidence supports your top-ranked workload, beyond it feeling important?
Which workload is ranked high because of readiness, and which because of upside?
What would have to be true for your ranking to be wrong?', N'Listen for rankings driven by the loudest stakeholder, readiness assumed rather than checked, upside estimated with no basis, and dependencies discovered after commitment. Also listen for a list that ranks everything and therefore prioritizes nothing.', N'Move from the ranked list to the one workload you will commit technical time to, and what evidence you still need.', N'If tooling is unavailable, map the workflow and human checkpoint manually, then draft the prompt for later testing.', N'Name the workload you are committing technical time to this week, the readiness evidence still missing, and who owns closing that gap.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Rank your workloads by readiness and impact, then commit technical time to the top one.', N'Bring the ranking, the workload you chose, and the readiness evidence still missing.'),
        (N'FG-ATS-TECH', N'WF-X-ARCH-01', N'ATS-TECH', N'Today is about develop a technical strategy and decision trajectory without turning the huddle into a tool demo or a status review.', N'The goal is A technical trajectory with priority bets, proof needs, owners, risks, milestones, and open decisions. AI can assemble evidence and draft options, but ATS judgment stays accountable for strategy, technical accuracy, and next decisions.', N'What is the next technical decision this customer has to make, and when?
Which of your technical bets is least supported by evidence?
What would have to be true for the customer to commit to the direction you are recommending?', N'Before the session: confirm access to the named tools, bring one real account or technical strategy example, and review the commitment from the prior huddle.', N'What is the next decision in the trajectory, and who makes it?
Which bet would you abandon first if evidence went against it?
What proof does the customer need before they will commit, and do you have a path to producing it?', N'Listen for a strategy that is a destination without a sequence, bets with no falsification condition, proof needs identified after the customer already asked, and milestones with no owner. Also listen for technical direction set without the customer''s own objectives in the room.', N'Move from the technical direction to the next decision it requires, with an owner and the evidence that unblocks it.', N'If tooling is unavailable, map the workflow and human checkpoint manually, then draft the prompt for later testing.', N'Name the next technical decision, its owner, the date it must happen by, and the proof the customer needs to make it.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Name the next technical decision on one account, its owner, and the date it must happen by.', N'Bring the decision, the owner who agreed to it, and the proof the customer needs.'),
        (N'FG-ATS-EBC', N'WF-X-CONV-01', N'ATS-EBC', N'Today is about design an executive briefing experience without turning the huddle into a tool demo or a status review.', N'The goal is An EBC plan with desired decisions, participants, evidence, preparation milestones, and follow-through ownership. AI can assemble evidence and draft options, but ATS judgment stays accountable for strategy, technical accuracy, and next decisions.', N'What is the one thing the customer should leave the briefing believing?
Who in the room can actually approve the next step?
What would make this briefing worth their time rather than ours?', N'Before the session: confirm access to the named tools, bring one real account or technical strategy example, and review the commitment from the prior huddle.', N'What will the customer do differently after this briefing?
Who in the room can approve that, and are they invited?
Which part of the agenda serves us rather than them?', N'Listen for agendas built around what we want to present, attendee lists without a decision maker, briefings with no ask, and content density that leaves no room for the customer to talk. Also listen for an experience designed for the meeting rather than for what happens after it.', N'Move from the briefing design to the single decision it is meant to produce and who must be present for that.', N'If tooling is unavailable, map the workflow and human checkpoint manually, then draft the prompt for later testing.', N'Name the briefing, the decision it should produce, and the one person who must be in the room for that decision to be possible.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Design one executive briefing around a single decision, and confirm the person who can make it will be there.', N'Bring the decision the briefing targets and confirmation the approver is invited.'),
        (N'FG-ATS-TALK', N'WF-X-CONV-01', N'ATS-TALK', N'Today is about adjust the technical talk track from customer signals without turning the huddle into a tool demo or a status review.', N'The goal is A signal-adjusted talk track with opening language, questions, objections, responses, and human review flags. AI can assemble evidence and draft options, but ATS judgment stays accountable for strategy, technical accuracy, and next decisions.', N'What did the customer say recently that should change how you talk about this?
Where is your current talk track still answering last quarter''s objection?
What signal are you choosing to ignore because it is inconvenient?', N'Before the session: confirm access to the named tools, bring one real account or technical strategy example, and review the commitment from the prior huddle.', N'What specifically did the customer say, and what did you infer from it?
Which part of your talk track is now answering a question they stopped asking?
What would you change if you took their last objection at face value?', N'Listen for signals interpreted to confirm what we already planned, talk tracks updated in wording but not in substance, and customer silence read as agreement. Also listen for adjustments based on one conversation with one person treated as the account''s position.', N'Move from the customer signal to the specific line in your talk track that has to change because of it.', N'If tooling is unavailable, map the workflow and human checkpoint manually, then draft the prompt for later testing.', N'Name the customer signal you are acting on and the specific line in your talk track that changes because of it.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Change one line in your talk track based on something a customer actually said this month.', N'Bring the customer signal and the line that changed because of it.'),
        (N'FG-ATS-TEAM', N'WF-X-ORCH-01', N'ATS-TEAM', N'Today is about mobilize the technical v-team around priorities and risks without turning the huddle into a tool demo or a status review.', N'The goal is A technical v-team alignment brief with owners, dependencies, investment signals, checkpoints, and next actions. AI can assemble evidence and draft options, but ATS judgment stays accountable for strategy, technical accuracy, and next decisions.', N'Who on your technical v-team could not state the current priority if asked today?
Which dependency has gone quiet in the last two weeks?
What are you carrying yourself that should belong to someone else?', N'Before the session: confirm access to the named tools, bring one real account or technical strategy example, and review the commitment from the prior huddle.', N'If I asked each v-team member the current priority, would I get the same answer?
Which dependency is at risk, and does its owner know?
What are you doing yourself that is really someone else''s accountability?', N'Listen for priorities that live only in the ATS''s head, owners assigned in a document but never agreed in a conversation, dependencies tracked without dates, and the ATS absorbing work because delegating it feels slower. Also listen for v-team meetings that report status without deciding anything.', N'Move from the coordination picture to one specific ask, to one named person, with a date.', N'If tooling is unavailable, map the workflow and human checkpoint manually, then draft the prompt for later testing.', N'Name one v-team ask you will send this week, to one named person, with a date and what you will supply to make it easy.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Send one specific v-team ask to one named person with a date and what you will supply.', N'Bring the ask you sent and whether it was accepted.'),
        (N'FG-SSP-ORIENT', N'WF-ORIENT-01', N'SSP-ORIENT', N'This session explains the motion and sets expectations for using AI in solution pursuit work.', N'Huddles are workflow-led, not tool demos. Every session ends with one thing to try. Human judgment stays explicit.', N'Which part of your week is assembling information rather than deciding anything?
Where do you already use AI, and where have you avoided it?
What would you need to see before you trusted an AI-drafted solution or pursuit output?', N'Before the session: confirm access to the tools named for this path, and come ready to describe the work you repeat most weeks. No prior AI experience is needed for this session.', N'Which solution or pursuit work do you repeat every week without thinking of it as a workflow?
Which of those steps is assembling information rather than making a decision?
Where must the SSP judgment stay human no matter how good the output gets?', N'Listen for unvoiced scepticism, access blockers stated as disinterest, the assumption that this is a tool rollout, and people who describe only their exceptional work rather than the work they repeat. The recurring, unglamorous tasks are the ones worth mapping.', N'Move from how the motion works to the recurring work each person will map with the discovery prompt this week.', N'If tool access is not confirmed, still run the discovery conversation and record access blockers separately from interest. The discovery prompt can be run in whichever tool the person already has.', N'Close by pointing the team to the resources for next week''s topic and to the workflow-discovery prompt below. Week 1 is for finding the recurring work worth automating.', N'Which part of your week had you never thought of as a workflow until now? What would have to be true before you trusted AI with it?', N'Run this in Microsoft 365 Copilot, Cowork, or Scout before the next huddle, then bring the result to the session:

"I am a Solution Sales Professional at Microsoft and I want to find the recurring work in my week that AI could take on.
1. First, look at my calendar, mail and Teams activity from the last four weeks and tell me what you can see about where my time actually goes. If you cannot access that data, say so and move to step 2 rather than guessing.
2. Then ask me up to five short questions, one at a time, to cover the work that never shows up in a calendar or an inbox.
3. Then list the five things I do most often. For each one give an estimate of the time it costs me per month, whether it is best handled as a saved prompt, a reusable skill, a scheduled automation or an existing agent, and the one judgment that must stay mine.
4. Rank them by time returned and tell me which one to start with."', N'Bring the ranked list of the five things you repeat most, which of them looked like a prompt, skill, automation, or agent fit, and any AI experience from the week, including anything that did not work.'),
        (N'FG-SSP-LEAD', N'WF-X-OPP-01', N'SSP-LEAD', N'Lead and account signals are noisy. Today is about turning them into a focused follow-up plan.', N'Qualification is evidence work. Solution relevance, owner, message, consent, and next action must be explicit.', N'Which lead or signal deserves attention first? What evidence makes it real? Who owns the next action?', N'Before the session: bring one live solution pursuit, solution play, lead list, opportunity, or investment case relevant to this huddle; confirm tool access; review last commitment and evidence.', N'Which lead or account signal deserves follow-up first? What evidence supports solution relevance?', N'Listen for undifferentiated lead lists, vague ownership, weak message fit, and missing consent/context.', N'Move from noisy signals to one prioritized follow-up plan.', N'If systems are unavailable, manually rank one lead list and draft the prompt for later testing.', N'Commit to to ranking one lead or prospect list and owning the top next action.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Turn your top-priority lead into an actual first contact this week.', N'Bring the message you sent and whether the signal was worth following.'),
        (N'FG-SSP-PLAN', N'WF-X-PLAN-01', N'SSP-PLAN', N'A solution-selling plan is useful only if it changes pursuit execution. Today is about building a plan that can be worked.', N'Plan around customer outcome, solution play, stakeholders, proof needs, demo or workshop sequence, and next decision.', N'Which solution pursuit needs a clearer plan? What proof or stakeholder coverage is missing?', N'Before the session: bring one live solution pursuit, solution play, lead list, opportunity, or investment case relevant to this huddle; confirm tool access; review last commitment and evidence.', N'What makes this solution pursuit worth SSP time? What next decision is the plan built to advance?', N'Listen for generic solution plans, missing stakeholder coverage, unclear proof path, and no 30-day plan.', N'Move from plan structure to one active pursuit.', N'If tooling is unavailable, sketch the plan on paper and capture evidence gaps.', N'Commit to to building or improving one solution-selling plan for a live pursuit.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Map who really decides on one pursuit, then reach the person missing from your list.', N'Bring the decision map and the absence that carried the most risk.'),
        (N'FG-SSP-VALUE', N'WF-X-VALUE-01', N'SSP-VALUE', N'Value needs to be created before the conversation, not after the objection. Today is about the customer-specific story.', N'The customer defines value. Use sourced evidence, caveats, use cases, and a clear next ask.', N'What customer priority does this solution map to? Which claim is supported, assumed, or missing evidence?', N'Before the session: bring one live solution pursuit, solution play, lead list, opportunity, or investment case relevant to this huddle; confirm tool access; review last commitment and evidence.', N'Which customer priority does the value narrative serve? Which claims are sourced?', N'Listen for generic value claims, unsupported ROI, customer priorities inferred rather than sourced, and missing caveats.', N'Move from value logic to the conversation or proof it supports.', N'If evidence sources are unavailable, build the narrative skeleton and list missing proof.', N'Commit to to one customer-specific value narrative with sourced evidence and caveats.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Test the assumptions behind one value claim, and remove any claim you cannot defend.', N'Bring the assumption table and the claim you dropped.'),
        (N'FG-SSP-CONV', N'WF-X-CONV-01', N'SSP-CONV', N'Preparation is the difference between explaining a solution and advancing a decision.', N'Prepare discovery questions, proof points, likely objections, role contributions, and a primary/fallback ask. Rehearse where useful.', N'What decision should this conversation advance? What objection is most likely? What proof will you use?', N'Before the session: bring one live solution pursuit, solution play, lead list, opportunity, or investment case relevant to this huddle; confirm tool access; review last commitment and evidence.', N'What is the intended decision from this meeting? What objection is most likely?', N'Listen for meetings framed around content rather than customer decision, objections first discovered live, and unclear ask.', N'Move from preparation to rehearsal or next customer ask.', N'If Agent J.ai is unavailable, role-play manually with one person acting as the customer.', N'Pick one upcoming solution conversation and prepares the brief or rehearsal.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Find the unknown that would change your recommendation, and ask about it in your next conversation.', N'Bring the question you asked and what the answer changed.'),
        (N'FG-SSP-ORCH', N'WF-X-ORCH-01', N'SSP-ORCH', N'Pursuits stall at handoffs. Today is about making every role, partner, funding dependency, and checkpoint explicit.', N'Name the objective, contributors, asks, owners, dates, dependencies, and escalation points.', N'Which handoff is currently assumed rather than owned? Where could partner or funding support change the path?', N'Before the session: bring one live solution pursuit, solution play, lead list, opportunity, or investment case relevant to this huddle; confirm tool access; review last commitment and evidence.', N'Which role, partner, or funding dependency is assumed but not owned?', N'Listen for unnamed owners, handoffs without dates, partner input treated as optional, and funding status overstated.', N'Move from orchestration principles to one stalled handoff.', N'If systems are unavailable, map the contributor chain and identify the break point.', N'Make one stalled contributor, partner, or funding handoff explicit.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Send one specific, dated ask to each role you need on a live pursuit.', N'Bring the asks you sent and which were accepted.'),
        (N'FG-SSP-COMP', N'WF-X-DEAL-01', N'SSP-COMP', N'Competitive response should be built on customer context and proof, not generic battlecards.', N'Use current approved competitive evidence, win/loss context, differentiators, objections, risks, and review flags.', N'Which competitor or alternative is shaping the decision? What proof is strongest and where is it weak?', N'Before the session: bring one live solution pursuit, solution play, lead list, opportunity, or investment case relevant to this huddle; confirm tool access; review last commitment and evidence.', N'Which competitive claim matters to the customer decision? What proof supports it?', N'Listen for stale battlecard claims, unsupported competitor statements, and differentiators not tied to customer priorities.', N'Move from competitor context to one proof-backed response plan.', N'If current sources are unavailable, separate what is known, assumed, and requiring Researcher/SME validation.', N'Build one proof-backed competitive response for a live pursuit.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Build one objection handler tied to approved proof, and use it in a live conversation.', N'Bring the handler, the objection it met, and whether the proof held.'),
        (N'FG-SSP-DEAL', N'WF-X-DEAL-01', N'SSP-DEAL', N'The final SSP huddle is about the next decision, not the whole deal.', N'Inspect milestone readiness, stakeholder gaps, proof, blockers, dependencies, partner/funding needs, and owners.', N'What is the pursuit actually waiting on? What evidence or owner will clear the next decision?', N'Before the session: bring one live solution pursuit, solution play, lead list, opportunity, or investment case relevant to this huddle; confirm tool access; review last commitment and evidence.', N'What is the opportunity’s next real decision? What evidence or owner will clear it?', N'Listen for close-date language instead of next decision, unowned blockers, missing proof, and unclear stakeholder gaps.', N'Move from readiness inspection to a 14- to 30-day action plan.', N'If Sales Agent/MSXI is unavailable, inspect from known opportunity context and log source gaps.', N'Name the next decision on one solution opportunity and who owns each blocker.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Design the one conversation that would clear the next decision on a stalled opportunity.', N'Bring the conversation you designed and the decision it produced.'),
        (N'FG-SE-ORIENT', N'WF-ORIENT-01', N'SE-ORIENT', N'This huddle sets the working contract for SE use of AI: faster assembly, stronger evidence checks, and explicit human accountability.', N'The huddle motion is workflow-led, not a tool demo.
AI can assemble briefs, options, responses, and reusable packages, but SEs keep technical judgment and customer commitments.
Each huddle ends with one small test on live or sanitized work.', N'Which part of your week is assembling information rather than deciding anything?
Where do you already use AI, and where have you avoided it?
What would you need to see before you trusted an AI-drafted technical output?', N'Before the session: confirm access to the tools named for this path, and come ready to describe the work you repeat most weeks. No prior AI experience is needed for this session.', N'Which technical work do you repeat every week without thinking of it as a workflow?
Which of those steps is assembling information rather than making a decision?
Where must the SE judgment stay human no matter how good the output gets?', N'Listen for unvoiced scepticism, access blockers stated as disinterest, the assumption that this is a tool rollout, and people who describe only their exceptional work rather than the work they repeat. The recurring, unglamorous tasks are the ones worth mapping.', N'Move from how the motion works to the recurring work each person will map with the discovery prompt this week.', N'If tool access is not confirmed, still run the discovery conversation and record access blockers separately from interest. The discovery prompt can be run in whichever tool the person already has.', N'Close by pointing the team to the resources for next week''s topic and to the workflow-discovery prompt below. Week 1 is for finding the recurring work worth automating.', N'Which part of your week had you never thought of as a workflow until now? What would have to be true before you trusted AI with it?', N'Run this in Microsoft 365 Copilot, Cowork, or Scout before the next huddle, then bring the result to the session:

"I am a Solution Engineer at Microsoft and I want to find the recurring work in my week that AI could take on.
1. First, look at my calendar, mail and Teams activity from the last four weeks and tell me what you can see about where my time actually goes. If you cannot access that data, say so and move to step 2 rather than guessing.
2. Then ask me up to five short questions, one at a time, to cover the work that never shows up in a calendar or an inbox.
3. Then list the five things I do most often. For each one give an estimate of the time it costs me per month, whether it is best handled as a saved prompt, a reusable skill, a scheduled automation or an existing agent, and the one judgment that must stay mine.
4. Rank them by time returned and tell me which one to start with."', N'Bring the ranked list of the five things you repeat most, which of them looked like a prompt, skill, automation, or agent fit, and any AI experience from the week, including anything that did not work.'),
        (N'FG-SE-CONV', N'WF-X-CONV-01', N'SE-CONV', N'Technical responses move faster when supported answers, assumptions, confidence, exceptions, and required reviewers are visible.', N'Answer with sources and confidence, not just fluency.
Preserve unsupported areas instead of smoothing them over.
Use the response package to route review, not to bypass it.', N'Which technical answer needs evidence before it can be used?
Where do we usually hide uncertainty?
Who must review the response before it goes to the customer?', N'Bring one RFP question, security or architecture questionnaire item, technical ask, or objection that requires a governed response.', N'Which answer is most consequential?
What source supports it?
Where should the response show confidence, caveat, exception, or SME-needed flag?', N'Listen for confident but unsourced answers, hidden uncertainty, overbroad commitments, and missing reviewers.', N'Move from answer drafting to response governance and exception routing.', N'If sources are not approved, create the exception list and reviewer path instead of drafting final language.', N'Commit to to one technical answer matrix or exception list with reviewer flags.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Prepare one technical conversation by finding the unknown that would change your recommendation.', N'Bring the unknown you found and the question you used to close it.'),
        (N'FG-SE-ARCH-1', N'WF-X-ARCH-01', N'SE-ARCH-1', N'Architecture validation works best when options, criteria, assumptions, and risks are visible before the technical debate starts.', N'Compare options against the agreed decision criteria.
Name the assumptions and validation steps, not just the recommended design.
Use AI to assemble evidence and decision records while keeping architecture judgment human.', N'Which architecture assumption would hurt most if wrong?
What criteria will decide between options?
What validation step should happen before the customer sees the recommendation?', N'Bring one architecture decision, relevant customer criteria, approved technical sources, and known constraints.', N'Which option should be compared, and against what criteria?
Which assumption needs validation first?
What would make the architecture recommendation unsafe to share?', N'Listen for unchallenged assumptions, uncited guidance, missing security or operations review, and options that are not tied to criteria.', N'Move from option comparison to creating the architecture decision record.', N'If authoritative sources are unavailable, identify required sources and reviewers before drafting.', N'Commit to to one architecture assumption or option you will validate against agreed criteria.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Design one solution and name the constraint that most limits it.', N'Bring the design and the constraint you validated.'),
        (N'FG-SE-ARCH-2', N'WF-X-ARCH-01', N'SE-ARCH-2', N'A demo or workshop should advance a customer decision, not tour a product. Today narrows the experience to proof that matters.', N'Anchor the experience in the customer scenario and decision.
Prepare evidence, objections, roles, environment needs, and fallback plan.
Do not rely on demo energy to cover unclear criteria.', N'What decision should the demo or workshop make easier?
Which scenario proves the most important customer concern?
Where could environment, permission, or data issues derail the experience?', N'Bring one demo, workshop, or technical customer session and the decision it needs to advance.', N'What decision should the demo or workshop advance?
Which scenario proves that decision?
What could fail because of data, tenant, permission, or environment constraints?', N'Listen for feature tours, unclear audience, unsupported claims, missing fallback plans, and proof not tied to criteria.', N'Move from scenario selection to the demo or workshop plan.', N'If the environment is unavailable, build the plan and mark environment validation as the human checkpoint.', N'Commit to to one demo or workshop plan tied to a specific customer decision.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Build one demo or workshop around the customer''s decision rather than the product''s features.', N'Bring what you cut and what the customer actually asked about.'),
        (N'FG-SE-ARCH-3', N'WF-X-ARCH-01', N'SE-ARCH-3', N'A PoC is valuable only if it has a bounded hypothesis, success criteria, and an exit decision before work starts.', N'Define the smallest useful proof.
Make success, exit, milestones, owners, dependencies, and review gates observable.
Pressure-test readiness before the customer or delivery team absorbs ambiguity.', N'What is the smallest proof that would answer the technical decision?
Which success criterion is too vague?
What should trigger exit, handoff, or no-go?', N'Bring one proposed PoC or proof motion, constraints, resources, dependencies, and desired technical decision.', N'What is the smallest useful proof?
Which success criterion is measurable?
Which dependency or owner is missing?', N'Listen for vague success criteria, PoCs that duplicate demo work, unowned dependencies, and no exit path.', N'Move from proof idea to readiness pressure test.', N'If customer data or resources are unavailable, use the missing dependency as the main readiness finding.', N'Commit to to one PoC scope revision that improves success criteria, dependencies, or exit path.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Scope one proof with success criteria and a stop condition agreed before it starts.', N'Bring the criteria, the stop condition, and who agreed to them.'),
        (N'FG-SE-DISC', N'WF-X-DISC-01', N'SE-DISC', N'Discovery should end with decision criteria, not a second discovery meeting. Today focuses on making the customer decision explicit early.', N'Start from the customer decision and work backward to criteria and evidence.
Separate sourced facts from hypotheses and open questions.
Capture what must be validated before architecture, demo, or PoC work begins.', N'Which decision is the customer actually trying to make?
What evidence gap would make the next technical step unsafe?
What criteria need to be agreed rather than inferred?', N'Bring one upcoming or recent technical discovery conversation, approved context, known constraints, and any open technical questions.', N'Which discovery question would most change the technical decision?
What evidence is missing or only assumed?
Which criteria must be agreed with the customer?', N'Listen for vague decisions, inferred criteria, missing evidence, and questions that sound impressive but do not advance the decision.', N'Move from discovery discussion to building the actual decision-criteria brief.', N'If tooling is unavailable, draft the criteria and evidence-gap structure manually.', N'Commit to to one discovery brief that includes decision criteria and evidence gaps.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Run one discovery conversation with the decision criteria written down before you go in.', N'Bring the criteria you took in and the one that turned out to be wrong.'),
        (N'FG-SE-HEALTH', N'WF-X-HEALTH-01', N'SE-HEALTH', N'Technical risk should be named while it is still a decision, not after it becomes a customer escalation.', N'Inspect exit criteria, blockers, proof gaps, objections, dependencies, and handoffs.
Every risk needs evidence, owner, mitigation, checkpoint, and next decision.
Use AI to surface signals, but use SE judgment to prioritize them.', N'What technical risk is blocking progression right now?
Which proof gap is being treated as if it were already closed?
Who owns the next technical action?', N'Bring one opportunity or technical workstream with a blocker, proof gap, objection, or dependency.', N'Which technical risk is blocking progression?
What evidence would clear or confirm it?
Who owns the mitigation and next checkpoint?', N'Listen for risks without owners, proof gaps treated as closed, delivery handoffs without requirements, and blockers framed too broadly.', N'Move from risk naming to action plan and handoff.', N'If opportunity context is unavailable, build the risk register from known facts and flag missing source context.', N'Name one technical risk, the evidence needed, the owner, and the next checkpoint.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Identify one technical risk early enough to be a conversation rather than an escalation.', N'Bring the risk, when you found it, and what you did about it.'),
        (N'FG-SE-ASSET', N'WF-X-ASSET-01', N'SE-ASSET', N'Reuse only works when an asset has enough context for someone else to trust and adapt it.', N'Package purpose, prerequisites, steps, parameters, validation checks, limitations, owner, and example use.
Remove sensitive content before reuse.
Use Skill Blueprints for repeatable workflows that are not validated assets yet.', N'What did you build recently that another SE will rebuild?
What context would make someone trust and adapt it?
What should not be reused without review?', N'Bring one demo, script, architecture, checklist, response, or pattern that could become reusable.', N'Which asset is worth reusing?
What context would make it usable by another SE?
What must be removed, validated, or tested before sharing?', N'Listen for assets without owner, missing prerequisites, sensitive content, unclear limitations, and reuse patterns that should become blueprints.', N'Move from asset selection to packaging or Skill Blueprint creation.', N'If the repository location is unclear, package the asset and record the placement decision as a blocker.', N'Package one reusable technical asset or drafts one Skill Blueprint.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Turn one piece of work you already did into something another SE could reuse.', N'Bring the asset and who you gave it to.'),
        (N'FG-CE-ORIENT', N'WF-ORIENT-01', N'CE-ORIENT', N'This is the session that explains the rest. Be honest about scepticism now rather than carrying it for eight weeks.', N'Huddles are 30 minutes and workflow-led, not tool demos.
Every session ends with one thing you will try.
Human judgment stays explicit at every step. That is the point, not a caveat.', N'Which part of your week is assembling information rather than deciding anything?
Where do you already use AI, and where have you avoided it?
What would you need to see before you trusted an AI-drafted commercial output?', N'Before the session: confirm access to the tools named for this path, and come ready to describe the work you repeat most weeks. No prior AI experience is needed for this session.', N'Which commercial work do you repeat every week without thinking of it as a workflow?
Which of those steps is assembling information rather than making a decision?
Where must the CE judgment stay human no matter how good the output gets?', N'Listen for unvoiced scepticism, access blockers stated as disinterest, the assumption that this is a tool rollout, and people who describe only their exceptional work rather than the work they repeat. The recurring, unglamorous tasks are the ones worth mapping.', N'Move from how the motion works to the recurring work each person will map with the discovery prompt this week.', N'If tool access is not confirmed, still run the discovery conversation and record access blockers separately from interest. The discovery prompt can be run in whichever tool the person already has.', N'Close by pointing the team to the resources for next week''s topic and to the workflow-discovery prompt below. Week 1 is for finding the recurring work worth automating.', N'Which part of your week had you never thought of as a workflow until now? What would have to be true before you trusted AI with it?', N'Run this in Microsoft 365 Copilot, Cowork, or Scout before the next huddle, then bring the result to the session:

"I am a Commercial Executive at Microsoft and I want to find the recurring work in my week that AI could take on.
1. First, look at my calendar, mail and Teams activity from the last four weeks and tell me what you can see about where my time actually goes. If you cannot access that data, say so and move to step 2 rather than guessing.
2. Then ask me up to five short questions, one at a time, to cover the work that never shows up in a calendar or an inbox.
3. Then list the five things I do most often. For each one give an estimate of the time it costs me per month, whether it is best handled as a saved prompt, a reusable skill, a scheduled automation or an existing agent, and the one judgment that must stay mine.
4. Rank them by time returned and tell me which one to start with."', N'Bring the ranked list of the five things you repeat most, which of them looked like a prompt, skill, automation, or agent fit, and any AI experience from the week, including anything that did not work.'),
        (N'FG-CE-HEALTH', N'WF-X-HEALTH-01', N'CE-HEALTH', N'Risk you find this week is a conversation. The same risk found by the customer is an escalation. Today is about finding it earlier.', N'A health score can tell you something is wrong. It rarely tells you what to do.
Every risk needs an owner and a date or it is an observation.
AI is good at surfacing signal. Prioritizing it is judgment.', N'Which account is at risk in a way the reporting does not show?
What stops a known risk from getting an owner?
Which part of this carries policy or precedent risk?', N'Before the session: confirm tool access for this huddle, bring one real commercial structure and policy example you are working on now, and review the commitment you made last week.', N'Which activity here is closest to what you are working on this week?
What would you need to see before you trusted the output?
Where would this break in your real commercial structure and policy work?', N'Through the lens of commercial structure and policy, listen for: risk described without an owner or a date; health reported by score rather than cause; and interventions discussed but never started.', N'Move from how risk surfaces to one account that is actually at risk now.', N'If status data is unavailable, work from what people know and note where the evidence should have come from.', N'Name one risk, one intervention and one owner.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Rank your commercial risks, then take the top one to its owner with a proposed intervention.', N'Bring the risk, the intervention, and the authoritative source behind it.'),
        (N'FG-CE-DEAL-1', N'WF-X-DEAL-01', N'CE-DEAL-1', N'Commercial structure decides whether a deal can move. Today is about comparing options before the structure hardens.', N'The goal is not to create an offer. The goal is to compare viable structures, surface trade-offs, and name the approval path while options still exist.', N'What option is the deal implicitly assuming? Which approval or exception would surprise the team later? What trade-off should be explicit before negotiation?', N'Before the session: bring one live opportunity, approved commercial context, known constraints, and the current approval or exception question.', N'Which commercial option is most plausible? What trade-off would change the decision? Where would this break if an approval requirement appears late?', N'Listen for: one default structure being treated as the only option; approval path ambiguity; pricing, term, or concession trade-offs not stated; and assumptions that need CE or Deal Desk review.', N'Move from possible structures to the smallest options matrix that makes the decision clearer.', N'If tooling is unavailable, build the options matrix manually and name the missing source evidence.', N'Create one commercial options matrix and names the approval path or missing evidence.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Build a commercial options matrix for one live deal and identify which option needs approval you do not hold.', N'Bring the options, the trade-offs, and the approval requirement you found.'),
        (N'FG-CE-DEAL-2', N'WF-X-DEAL-01', N'CE-DEAL-2', N'Reviewers do not need more history. They need the recommendation, options, assumptions, risks, and decision requested.', N'A commercial decision narrative should separate facts from judgment. It should show why this structure, what alternatives were considered, and who must review it.', N'What would a reviewer need to say yes, no, or not yet? Which assumption is unsupported? What customer impact needs to be explained plainly?', N'Before the session: bring a reviewed deal option, known assumptions, transition considerations, and the audience for the recommendation.', N'Which recommendation would a reviewer understand quickly? What assumption needs evidence? Which reviewer or decision owner is missing?', N'Listen for: narratives that bury the ask; options without trade-offs; customer impact omitted; and transition or migration risks stated without a source.', N'Move from deal facts to the internal recommendation and the decision being requested.', N'If tooling is unavailable, draft the decision narrative outline and identify the evidence gaps.', N'Draft one commercial decision narrative with options, assumption flags, and required reviewers.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Write the commercial recommendation for one deal in a form a reviewer could act on without asking you a question.', N'Bring the recommendation and the assumption a reviewer challenged.'),
        (N'FG-CE-DEAL-3', N'WF-X-DEAL-01', N'CE-DEAL-3', N'Negotiation is where vague structure becomes expensive. Today is about authority boundaries, give/get logic, and rehearsal before the customer asks.', N'The agent can help prepare scenarios and objections. The CE stays accountable for authority, customer commitments, concession discipline, and escalation triggers.', N'Where is your concession logic unclear? Which customer ask would trigger escalation? What must not be said before review?', N'Before the session: bring one negotiation scenario, approved position, authority boundaries, and any known customer asks.', N'Which customer ask would test your authority boundary? What give/get logic is clear enough to use? What must be reviewed before customer-facing use?', N'Listen for: concession logic that is not tied to value; authority boundaries not explicit; likely objections unrehearsed; and customer commitments that require review.', N'Move from negotiation principles to one realistic customer objection and the reviewed response.', N'If role-play tooling is unavailable, rehearse manually using the approved negotiation plan.', N'Rehearse one negotiation scenario and identifies authority, concession, and review boundaries.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Prepare one negotiation with your concession boundaries and escalation triggers set before the conversation.', N'Bring the plan, what you would not concede, and what actually happened.'),
        (N'FG-CE-ORCH', N'WF-X-ORCH-01', N'CE-ORCH', N'Commercial execution stalls when owners, evidence, and approval handoffs are implied. Today is about making them explicit.', N'Execution is not just follow-up. It is approval routing, evidence readiness, exception handling, ownership, and escalation without overstating authority.', N'Which handoff is implicit today? What evidence is missing for the next approver? Where could ECIF, Deal Desk, finance, policy, or legal review be needed?', N'Before the session: bring one in-flight deal or investment dependency, its known approval stage, and the evidence or owner currently missing.', N'Which handoff or approval is the deal actually waiting on? What evidence is missing? Who owns the next decision, and what should not be represented as approved?', N'Listen for: approval status overstated; handoffs without owners; ECIF, finance, Deal Desk, legal, or policy dependencies hidden; and blockers described without the next governed action.', N'Move from the full execution path to the single blocker and owner that must be handled next.', N'Use a sanitized scenario. If systems are unavailable, map the route, owner, evidence, and next decision without inferring approval state.', N'Name one approval or execution blocker, its owner, evidence needed, and next governed action.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Map the approval path for one deal and confirm the first owner knows it is coming.', N'Bring the path, the owners, and the blocker you cleared.'),
        (N'FG-CE-RENEW', N'WF-X-RENEW-01', N'CE-RENEW', N'Renewal risk is visible before the renewal date if commercial structure, value evidence, and approval needs are inspected early.', N'A renewal is not only a date. It is a commercial strategy with structure, risk, expansion potential, concessions, and approval path.', N'Which renewal risk is already visible? What expansion is supported by evidence? What approval or structure question should not wait?', N'Before the session: bring one renewal, approved context, current structure, risk signal, and expansion or approval question.', N'Which activity here is closest to what you are working on this week?
What would you need to see before you trusted the output?
Where would this break in your real commercial structure and policy work?', N'Through the lens of commercial structure and policy, listen for: renewals treated as administrative; risk noticed inside the last quarter; and expansion pursued without evidence of realized value.', N'Move from renewal principles to one renewal actually on the horizon.', N'If data is unavailable, work the renewal from what the team knows and note the evidence gaps.', N'Name one renewal risk, one supported expansion hypothesis, and the approval or structure question to resolve.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Build a renewal strategy for one account using real agreement and discount data, not recollection.', N'Bring the strategy, the data you retrieved, and the expansion you found or ruled out.'),
        (N'FG-CE-POLICY', N'WF-X-POLICY-01', N'CE-POLICY', N'Policy questions found at approval cost weeks. Today is about finding the question early and routing it to the authoritative owner.', N'AI can assemble the context and possible questions. It cannot interpret policy, approve exceptions, or invent authority. The useful output is a routed question with evidence, not a guessed answer.', N'Which policy or licensing question most often causes rework? Where did an approval path surprise you? Which interpretation must come from an authoritative source?', N'Before the session: bring one real commercial structure or policy example, the approved source you would check, and the decision or approval path currently unclear.', N'Which Practice helps you route the policy or licensing question fastest? What would you need to see before trusting the output? Where must the answer come from an authoritative owner instead of AI?', N'Through the lens of commercial structure and policy, listen for: policy interpreted from memory; uncertainty left unflagged; approval paths discovered late; and questions that need an authoritative owner rather than a generated answer.', N'Move from policy categories to one live deal question and the owner who can answer it.', N'If guidance is unavailable, list the questions, required evidence, and routing owner. Do not guess the answer.', N'Route one policy, licensing, or approval question to an authoritative owner with the evidence needed.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Take one open policy or licensing question to its authoritative owner rather than answering it yourself.', N'Bring the question, the owner, and the answer you received.'),
        (N'FG-CSA-ORIENT', N'WF-ORIENT-01', N'CSA-ORIENT', N'This is the session that explains the rest. Be honest about scepticism now rather than carrying it for eight weeks.', N'Huddles are 30 minutes and workflow-led, not tool demos.
Every session ends with one thing you will try.
Human judgment stays explicit at every step. That is the point, not a caveat.', N'Which part of your week is assembling information rather than deciding anything?
Where do you already use AI, and where have you avoided it?
What would you need to see before you trusted an AI-drafted architecture or delivery output?', N'Before the session: confirm access to the tools named for this path, and come ready to describe the work you repeat most weeks. No prior AI experience is needed for this session.', N'Which architecture or delivery work do you repeat every week without thinking of it as a workflow?
Which of those steps is assembling information rather than making a decision?
Where must the CSA judgment stay human no matter how good the output gets?', N'Listen for unvoiced scepticism, access blockers stated as disinterest, the assumption that this is a tool rollout, and people who describe only their exceptional work rather than the work they repeat. The recurring, unglamorous tasks are the ones worth mapping.', N'Move from how the motion works to the recurring work each person will map with the discovery prompt this week.', N'If tool access is not confirmed, still run the discovery conversation and record access blockers separately from interest. The discovery prompt can be run in whichever tool the person already has.', N'Close by pointing the team to the resources for next week''s topic and to the workflow-discovery prompt below. Week 1 is for finding the recurring work worth automating.', N'Which part of your week had you never thought of as a workflow until now? What would have to be true before you trusted AI with it?', N'Run this in Microsoft 365 Copilot, Cowork, or Scout before the next huddle, then bring the result to the session:

"I am a Cloud Solution Architect at Microsoft and I want to find the recurring work in my week that AI could take on.
1. First, look at my calendar, mail and Teams activity from the last four weeks and tell me what you can see about where my time actually goes. If you cannot access that data, say so and move to step 2 rather than guessing.
2. Then ask me up to five short questions, one at a time, to cover the work that never shows up in a calendar or an inbox.
3. Then list the five things I do most often. For each one give an estimate of the time it costs me per month, whether it is best handled as a saved prompt, a reusable skill, a scheduled automation or an existing agent, and the one judgment that must stay mine.
4. Rank them by time returned and tell me which one to start with."', N'Bring the ranked list of the five things you repeat most, which of them looked like a prompt, skill, automation, or agent fit, and any AI experience from the week, including anything that did not work.'),
        (N'FG-CSA-PIPE', N'WF-X-PIPE-01', N'CSA-PIPE', N'Most of us have at some point defended a number we were not fully sure about. Today is about fixing the signal, not the spreadsheet.', N'A gap is usually three problems wearing one label: not enough, not moving, or dated wrong.
Certified data settles arguments opinion cannot.
Correction is judgment work. The agent proposes, you decide.', N'Where do consumption or usage signals become technical work for you?
Which shortfall signal is most likely to hide a technical cause?
What evidence would you need before owning an intervention?', N'Before the session: confirm access to the relevant certified report, bring one consumption or usage signal you are reviewing, and note what technical context the report does not show.', N'Which consumption or shortfall activity is closest to what you inspect today?
What would you need to verify before trusting the signal?
Where would this break if the report lacks architecture context?', N'Through the CSA lens, listen for: report signals separated from technical cause; assumptions about customer intent; missing owners; and interventions that require architecture or workload context.', N'Move from the report signal to one technical cause or blocker that can be validated this week.', N'If the data source is unavailable, map the current inspection routine and draft the prompt and human checkpoint for later testing.', N'Name one consumption signal you will validate and one technical question you will answer.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Name the technical cause behind one consumption gap, and start the intervention with an owner.', N'Bring the cause you identified and who owns the intervention.'),
        (N'FG-CSA-CONV', N'WF-X-CONV-01', N'CSA-CONV', N'Preparation is rarely the thing people disagree about. The problem is finding an hour for it. Today is about making it take ten.', N'A brief is not a summary. It is a position plus the questions that would change it.
The intended outcome is the part most preparation leaves out, and it changes how the meeting runs.
Anticipated objections are cheaper than recovered ones.', N'Which upcoming conversation needs a recommendation, not just a summary?
What evidence would make the advisory position credible?
What customer decision should the conversation advance?', N'Before the session: bring one upcoming technical advisory conversation, the intended decision, and the approved sources you would trust for preparation.', N'Which advisory conversation is worth preparing with AI support?
What evidence would you need before using the recommendation?
Where would the conversation fail if the ask is not clear?', N'Through the CSA lens, listen for: preparation that summarizes but does not decide; evidence gaps; customer facts needing review; and advisory recommendations without a named decision.', N'Move from generic preparation to one upcoming conversation and its intended customer decision.', N'If tooling is unavailable, build the brief structure for a real upcoming meeting and note where the evidence would come from.', N'Pick one upcoming advisory conversation and names the decision it should advance.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Prepare one advisory conversation around the decision you need, not the content you have.', N'Bring the recommendation, the evidence, and the decision you asked for.'),
        (N'FG-CSA-ARCH-1', N'WF-X-ARCH-01', N'CSA-ARCH-1', N'A design that has not been argued against has not really been validated. Today is about the proof, not the diagram.', N'Design and proof are one motion. A design the customer cannot see is a document.
Success criteria set before the work are the only ones that count.
AI accelerates the assembly. The architecture judgment stays human.', N'Which architecture option is still being treated as obvious?
What decision criteria would change the recommendation?
What evidence would you need before supporting this design?', N'Before the session: bring one architecture decision or design assumption, the known constraints, and the evidence you would use to compare options.', N'Which architecture option comparison is worth doing now?
What decision criteria must be explicit before recommending?
Where could current guidance conflict or lack evidence?', N'Through the CSA lens, listen for: untested assumptions; option comparisons without decision criteria; public guidance used without applicability review; and controls, governance, or resilience claims needing SME validation.', N'Move from architecture principles to one live architecture decision with explicit criteria.', N'If the environment is unavailable, define the validation approach and the success criteria on paper.', N'Name one architecture assumption or option you will compare against explicit criteria.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Draft one production-ready design and name the dependency most likely to break it.', N'Bring the design and the dependency you validated.'),
        (N'FG-CSA-ARCH-2', N'WF-X-ARCH-01', N'CSA-ARCH-2', N'A design that has not been argued against has not really been validated. Today is about the proof, not the diagram.', N'Design and proof are one motion. A design the customer cannot see is a document.
Success criteria set before the work are the only ones that count.
AI accelerates the assembly. The architecture judgment stays human.', N'Which dependency could make the design fail in production?
What proof is small enough to validate the decision?
Who owns the next technical decision after validation?', N'Before the session: bring one validation path, proof plan, or delivery-readiness question tied to a real workload or customer scenario.', N'Which validation or proof plan would reduce delivery risk fastest?
What dependency must be owned before committing the design?
Where does ECIF or delivery-readiness change the technical plan?', N'Through the CSA lens, listen for: validation scoped too broadly; unowned prerequisites; proof criteria written after work begins; and investment-funded scope that may not be deliverable as designed.', N'Move from the design to the smallest validation path that can change the decision.', N'If the environment is unavailable, define the validation approach and the success criteria on paper.', N'Name one validation or delivery-readiness dependency you will make explicit.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Define the validation path for one design, including what would tell you to stop.', N'Bring the validation path and the stop condition you set.'),
        (N'FG-CSA-HEALTH', N'WF-X-HEALTH-01', N'CSA-HEALTH', N'Risk you find this week is a conversation. The same risk found by the customer is an escalation. Today is about finding it earlier.', N'A health score can tell you something is wrong. It rarely tells you what to do.
Every risk needs an owner and a date or it is an observation.
AI is good at surfacing signal. Prioritizing it is judgment.', N'Which technical risk is visible now but not yet owned?
What is evidence, and what is interpretation?
What intervention could prevent this from becoming customer-visible?', N'Before the session: bring one technical health signal, risk, or dependency you are tracking, plus the source you would use to validate it.', N'Which technical health activity is closest to a real account risk?
What evidence separates the risk from a hunch?
Who owns the intervention if the risk is real?', N'Through the CSA lens, listen for: health scores treated as causes; risks without owners or dates; technical blockers becoming customer-visible; and actions that require CSAM, support, delivery, or commercial alignment.', N'Move from health signal to one risk, its evidence, owner, and next intervention.', N'If status data is unavailable, work from what people know and note where the evidence should have come from.', N'Name one technical risk, its evidence, its owner, and the next intervention.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Find one technical health risk that is not visible in the data, and take it to its owner.', N'Bring the risk, where the signal came from, and who now owns it.'),
        (N'FG-CSA-VALUE-1', N'WF-X-VALUE-01', N'CSA-VALUE-1', N'Value without evidence tends to read as opinion. Today is about the evidence, and who needs to hear it.', N'The customer defines value. Our job is to evidence it in their terms.
Causality is easy to claim and hard to support. Say what the data supports.
A value story nobody hears is not value realized.', N'Which technical progress has not yet been translated into customer value?
Which cost, consumption, or optimization signal is credible enough to use?
What claim would you refuse to make without stronger evidence?', N'Before the session: bring one optimization, consumption, or delivery-progress signal and the outcome it might support.', N'Which optimization or progress signal could become a value story?
What financial or technical claim requires review?
What evidence is missing before recommending action?', N'Through the CSA lens, listen for: invented savings; correlation presented as causality; optimization divorced from architecture tradeoffs; and value claims not tied to supported outcomes.', N'Move from the signal to one bounded recommendation or technical value narrative.', N'If evidence sources are unavailable, build the value structure and identify what evidence you would need.', N'Commit to to one evidence-backed optimization or technical value recommendation.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Evidence one technical outcome in terms the customer would use themselves.', N'Bring the outcome, the evidence, and how you phrased it.'),
        (N'FG-CSA-VALUE-2', N'WF-X-VALUE-01', N'CSA-VALUE-2', N'Value without evidence tends to read as opinion. Today is about the evidence, and who needs to hear it.', N'The customer defines value. Our job is to evidence it in their terms.
Causality is easy to claim and hard to support. Say what the data supports.
A value story nobody hears is not value realized.', N'What value story would the customer actually recognize?
Which evidence supports the story, and which part is still only expected?
What next technical action would make the value more real?', N'Before the session: bring one technical review, business review, or value-realization example and the evidence behind it.', N'Which customer review package would benefit from AI assembly?
What evidence must travel with the value story?
Which next technical action makes the value more credible?', N'Through the CSA lens, listen for: progress not connected to agreed outcomes; unsupported realization claims; missing source links; and follow-through that lacks owners.', N'Move from value language to the evidence package and next technical action.', N'If evidence sources are unavailable, build the value structure and identify what evidence you would need.', N'Commit to to one technical value story and the evidence that will travel with it.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Produce one costed optimization recommendation the customer could act on this quarter.', N'Bring the recommendation, the cost basis, and the customer response.'),
        (N'FG-CSAM-ORIENT', N'WF-ORIENT-01', N'CSAM-ORIENT', N'This is the session that explains the motion through the CSAM lens: less status assembly, more customer outcome leadership.', N'Huddles are 30 minutes and workflow-led. CSAM work stays human-led: AI helps gather, synthesize, draft and monitor; the CSAM validates context, trust, commitments and customer-facing messages.', N'Which part of your week is assembling information rather than deciding anything?
Where do you already use AI, and where have you avoided it?
What would you need to see before you trusted an AI-drafted customer success output?', N'Before the session: confirm access to the tools named for this path, and come ready to describe the work you repeat most weeks. No prior AI experience is needed for this session.', N'Which customer success work do you repeat every week without thinking of it as a workflow?
Which of those steps is assembling information rather than making a decision?
Where must the CSAM judgment stay human no matter how good the output gets?', N'Listen for unvoiced scepticism, access blockers stated as disinterest, the assumption that this is a tool rollout, and people who describe only their exceptional work rather than the work they repeat. The recurring, unglamorous tasks are the ones worth mapping.', N'Move from how the motion works to the recurring work each person will map with the discovery prompt this week.', N'If tool access is not confirmed, still run the discovery conversation and record access blockers separately from interest. The discovery prompt can be run in whichever tool the person already has.', N'Close by pointing the team to the resources for next week''s topic and to the workflow-discovery prompt below. Week 1 is for finding the recurring work worth automating.', N'Which part of your week had you never thought of as a workflow until now? What would have to be true before you trusted AI with it?', N'Run this in Microsoft 365 Copilot, Cowork, or Scout before the next huddle, then bring the result to the session:

"I am a Customer Success Account Manager at Microsoft and I want to find the recurring work in my week that AI could take on.
1. First, look at my calendar, mail and Teams activity from the last four weeks and tell me what you can see about where my time actually goes. If you cannot access that data, say so and move to step 2 rather than guessing.
2. Then ask me up to five short questions, one at a time, to cover the work that never shows up in a calendar or an inbox.
3. Then list the five things I do most often. For each one give an estimate of the time it costs me per month, whether it is best handled as a saved prompt, a reusable skill, a scheduled automation or an existing agent, and the one judgment that must stay mine.
4. Rank them by time returned and tell me which one to start with."', N'Bring the ranked list of the five things you repeat most, which of them looked like a prompt, skill, automation, or agent fit, and any AI experience from the week, including anything that did not work.'),
        (N'FG-CSAM-SPLAN', N'WF-X-PLAN-01', N'CSAM-SPLAN', N'Success planning is not documentation. It is how the customer and Microsoft agree what progress means.', N'A plan should name outcomes, milestones, owners, risks and review points. AI can draft and inspect the plan, but only the CSAM can validate the customer priority and commitment.', N'When did your success plan last change because the customer''s priorities changed?
Which milestone in it would the customer not recognize as theirs?
What is in the plan because it is genuinely the outcome, and what is there because it was easy to measure?', N'Before the session: bring one active customer priority, its current CSP or success-plan notes and the latest review or action list.', N'Which outcome in your plan is stated in the customer''s words rather than ours?
Which milestone has drifted without anyone deciding to move it?
What would you remove from the plan today to make it governable?', N'Listen for plans built around Microsoft milestones rather than customer outcomes, measures chosen because they are available rather than meaningful, owners who have never agreed to their commitment, and plans so long that nobody governs them. Also listen for drift being reported rather than decided.', N'Move from the plan as it stands to the single outcome you will make observable this week.', N'If the tool or data source is unavailable, map the current workflow manually, name the trusted sources and draft the prompt plus human checkpoint for later testing.', N'Name the customer, the one outcome you will make observable this week, and what you will remove from the plan to keep it governable.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Make one success plan outcome observable this week, and remove something to keep the plan governable.', N'Bring the outcome you made measurable and what you removed.'),
        (N'FG-CSAM-HEALTH', N'WF-X-HEALTH-01', N'CSAM-HEALTH', N'Today is about moving from signal review to intervention. Scores help, but action changes the customer trajectory.', N'Health work spans adoption, usage, support, delivery, sentiment and stakeholder change. The CSAM must separate noise from the risk that matters most right now.', N'Which customer worries you for reasons the health score does not capture?
What did someone say in a recent conversation that has not made it into any system?
Which risk have you been watching rather than acting on, and why?', N'Before the session: bring one account with visible health, adoption, support or delivery risk and the current owner or open question.', N'What is the driver behind the score, not the score itself?
Which signal came from a person rather than a system, and did it survive into the record?
Who owns the intervention, and by when does it have to start to matter?', N'Listen for health scores treated as the diagnosis rather than the symptom, risks the team has normalized, interventions without owners, and conversation-based signals that never reached the data. Also listen for the customer''s own view of their health being absent from the discussion.', N'Move from the ranked health view to one intervention with an owner, a due date, and an escalation threshold.', N'If the tool or data source is unavailable, map the current workflow manually, name the trusted sources and draft the prompt plus human checkpoint for later testing.', N'Name the top risk, its actual driver rather than its score, the owner who has agreed to the intervention, and the escalation threshold.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Find the driver behind one health score, then take the intervention to an owner who agrees to it.', N'Bring the driver, the owner, and the escalation threshold you set.'),
        (N'FG-CSAM-EXEC', N'WF-X-CONV-01', N'CSAM-EXEC', N'Executive alignment is where customer success becomes visible to the people who can sponsor, unblock or redirect it.', N'Stakeholder maps should show influence, decision rights, relationship health and the next ask. AI can assemble signals; the CSAM decides the message and timing.', N'Who is the most senior person at this customer you have never spoken to directly?
Which stakeholder could stop this work, and do you know what they care about?
When an executive last engaged, what did they actually want from us?', N'Before the session: bring one upcoming executive or sponsor conversation and the latest stakeholder context.', N'Which stakeholder can stop this, and what do they need to believe?
Where is your coverage a title on a map rather than a relationship?
What would you ask the executive for if you had fifteen minutes tomorrow?', N'Listen for stakeholder maps built from org charts rather than observed behavior, executive relationships that exist only through an intermediary, engagement plans with no ask, and blockers identified without a plan to reach them. Also listen for assuming a quiet stakeholder is a supportive one.', N'Move from the stakeholder map to the one relationship you will build this month and the reason they would take the meeting.', N'If the tool or data source is unavailable, map the current workflow manually, name the trusted sources and draft the prompt plus human checkpoint for later testing.', N'Name the stakeholder you will reach this month, what that person needs to believe, and who can make the introduction.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Reach one stakeholder you have never spoken to directly, and know what they care about before you do.', N'Bring who you reached, how, and what you learned that you did not expect.'),
        (N'FG-CSAM-ORCH', N'WF-X-ORCH-01', N'CSAM-ORCH', N'CSAM orchestration is making the customer-success system observable enough to run.', N'Handoffs need an input, owner and date. Escalation is not a failure when it is used to unblock the system and protect customer outcomes.', N'Where does work currently stop between Microsoft, the partner, and the customer?
Who believes they own something that someone else also believes they own?
Which handoff have you personally been compensating for?', N'Before the session: bring one workstream involving Microsoft, customer, partner, support or delivery handoffs.', N'Where exactly does work stop between the three parties?
Who thinks they own that step, and have you asked them?
What are you personally absorbing because the handoff does not work?', N'Listen for the CSAM compensating for a broken handoff rather than fixing it, ownership assumed across company boundaries, partner commitments with no date, and coordination meetings that report rather than decide. Also listen for the customer''s own team being left out of the orchestration picture.', N'Move from the coordination map to the one handoff you will make explicit, with both sides named.', N'If the tool or data source is unavailable, map the current workflow manually, name the trusted sources and draft the prompt plus human checkpoint for later testing.', N'Name the handoff you will make explicit, both parties by name, and the date it will be agreed rather than assumed.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Make one handoff explicit this week by agreeing it with both sides rather than assuming it.', N'Bring the handoff, both owners, and the date it was agreed.'),
        (N'FG-CSAM-VALUE', N'WF-X-VALUE-01', N'CSAM-VALUE', N'Adoption activity does not automatically become customer value. Today is about proving and accelerating value realization.', N'Adoption plans should link underused features, customer priorities, behavior-change actions, milestones and value evidence. AI can draft the plan and value narrative; the CSAM validates truth and relevance.', N'What value has this customer actually realized that you could prove today?
Where is adoption stalled, and do you know why or are you guessing?
What would the customer say they got, if asked without us in the room?', N'Before the session: bring one workload or solution where adoption progress, friction or value proof needs to be clarified.', N'What value can you evidence today, and what are you asserting?
Where adoption stalled, do you know the cause or are you inferring it?
Would the customer describe the value the same way you just did?', N'Listen for value claimed from usage figures alone, adoption barriers guessed rather than investigated, realized value described in Microsoft terms rather than customer outcomes, and proof that would not survive a procurement conversation. Also listen for value stories that have never been said back to the customer.', N'Move from the value picture to one claim you will evidence, and one adoption barrier you will actually diagnose.', N'If the tool or data source is unavailable, map the current workflow manually, name the trusted sources and draft the prompt plus human checkpoint for later testing.', N'Name one value claim you will evidence, one adoption barrier you will diagnose rather than guess at, and how you will say it back to the customer.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Evidence one value claim, and diagnose one adoption barrier instead of guessing at it.', N'Bring the evidenced claim and what you found was actually blocking adoption.'),
        (N'FG-CSAM-RENEW', N'WF-X-RENEW-01', N'CSAM-RENEW', N'Renewal readiness starts before the renewal motion. Today is about seeing risk and growth conditions early.', N'Consumption, MACC or usage trajectory, adoption gaps, value evidence, support health and stakeholder signals all shape renewal confidence.', N'Which renewal are you least confident about, and what specifically drives that?
What consumption signal would you want to see six months before a renewal conversation?
Where is growth genuinely available versus where are you hoping?', N'Before the session: bring one account with renewal, consumption, usage or expansion relevance in the near planning horizon.', N'What is your forecast based on, and how far ahead does the signal reach?
Which growth opportunity is supported by consumption evidence?
What would you need to know now to avoid a surprise at renewal?', N'Listen for forecasts driven by relationship confidence rather than consumption evidence, growth assumed from headroom rather than intent, renewal risk surfacing late because nobody looked early, and commercial ownership blurring between CSAM and CE. Also listen for consumption trends read without seasonality.', N'Move from the forecast to the one early signal you will start tracking, and who you will align it with.', N'If the tool or data source is unavailable, map the current workflow manually, name the trusted sources and draft the prompt plus human checkpoint for later testing.', N'Name the renewal you are least confident about, the early signal you will start tracking, and who you will align the forecast with.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Start tracking one early consumption signal and hand it to the account owner.', N'Bring the signal, why it matters, and who you handed it to.'),
        (N'FG-CSAM-ESCALATE', N'WF-X-HEALTH-01', N'CSAM-ESCALATE', N'Escalations test trust. Today is about moving from scattered status to a grounded recovery plan.', N'A useful brief names customer impact, current status, owner, decision needed, next action and update cadence. AI can consolidate threads; the CSAM validates tone, accuracy and accountability.', N'What issue are you currently managing that should probably already be escalated?
What is holding you back: evidence, ownership, or the conversation itself?
When an escalation last worked well, what made it work?', N'Before the session: bring one live or recent delivery risk, incident, support issue or overdue commitment.', N'What threshold would have told you to escalate this a month ago?
What does the recovery plan commit us to, and can we deliver it?
What will you tell the customer, and when?', N'Listen for escalation delayed to avoid an uncomfortable conversation, recovery plans that promise more than delivery can support, customer communication planned after the internal fix rather than alongside it, and escalations raised without a defined exit. Also listen for the same issue recurring without anyone treating the pattern.', N'Move from the delivery risk to a recovery plan with an owner, a customer message, and a defined exit condition.', N'If the tool or data source is unavailable, map the current workflow manually, name the trusted sources and draft the prompt plus human checkpoint for later testing.', N'Name the risk you will escalate or resolve this week, the recovery commitment delivery can actually support, and what the customer will be told.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Take one issue to escalation or resolution this week, with a recovery commitment delivery can actually support.', N'Bring the issue, the recovery plan, and what the customer was told.'),
        (N'FG-AE-INVEST', N'WF-INVEST-01', N'AE-INVEST', N'Investment should be connected to a real customer barrier, not added as a side process. Today is about the AE’s role in naming the investment hypothesis and routing the next decision.', N'Eligibility, funding, and approval are governed human decisions. AI may help assemble context, status, and evidence, but the AE should not overstate approval or commitment.', N'Where could investment remove a barrier? Which part is yours to advance? Who owns the next governed decision?', N'Before the session: bring one live opportunity or account barrier where investment may be relevant, plus any approved context you can safely use.', N'Where might investment remove a real barrier? What evidence supports that barrier? Who owns eligibility, funding, approval, delivery, or value proof?', N'Listen for funding implied as approved, hidden open questions, unowned handoffs, and investment ideas not tied to an account priority or decision.', N'Move from investment concept to the AE’s next governed action on one live case.', N'Use a sanitized scenario if live data is not appropriate. Do not infer eligibility, approval, or funding status.', N'Name the investment hypothesis, evidence gap, and next governed owner.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Test whether investment could remove one real barrier, then route the next decision without implying approval.', N'Bring the investment hypothesis, source evidence, open questions, owner, and the next governed action.'),
        (N'FG-AE-ORCH', N'WF-X-ORCH-01', N'AE-ORCH', N'AE orchestration works when everyone knows the customer decision, their role, the handoff, and the date. Today is about making that operating model explicit.', N'AEs often lead through influence without direct authority. AI can assemble commitments, role gaps, partner context, and follow-up drafts; the AE decides who to pull in and how to lead the motion.', N'Where is the handoff currently vague? Which role or partner is missing? What would reduce follow-up noise this week?', N'Before the session: bring one live account or opportunity that depends on multiple Microsoft roles, partners, or delivery handoffs.', N'Which role, partner, or handoff is missing right now? What input does each owner need? What follow-up should be automated or drafted, and what should remain relationship-led?', N'Listen for responsibility without authority, handoffs assumed rather than confirmed, partner motions added late, and meetings where every role attends but no owner is clear.', N'Move from role discussion to an owner/date/input map for one opportunity.', N'If systems are unavailable, map the handoff chain manually and capture the prompt or workflow to run later.', N'Name one handoff, role gap, or partner action you will make explicit this week.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Create or update one account-team operating brief with owners, inputs, dates, and next customer decision.', N'Bring the role/partner map, handoff list, follow-up message or plan, and what changed after owner validation.'),
        (N'FG-AE-VALUE', N'WF-X-VALUE-01', N'AE-VALUE', N'A QBR or executive cadence should not be a status meeting. It should make value, commitments, risks, and strategic asks visible enough for the customer to decide.', N'AI can assemble outcomes, usage signals, open commitments, risks, investments, and expansion plays. The AE validates what the customer would recognize as value and which ask advances the relationship.', N'What value has been delivered but not evidenced? Which customer commitment is still open? What strategic ask should the QBR create?', N'Before the session: bring one account with a QBR, SBR, renewal, or executive follow-up where value evidence matters.', N'What value would the customer recognize? Which outcome is supported by evidence, and which is only expected? What strategic ask should follow from the value story?', N'Listen for value claims without evidence, QBRs that become status readouts, unsupported causality, missing customer commitments, and expansion asks not tied to outcomes.', N'Move from value evidence to the executive brief or QBR ask the AE would actually use.', N'If evidence sources are unavailable, build the value structure and mark each claim as supported, assumed, or needs review.', N'Name one value claim to evidence and one strategic ask to sharpen.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Build one executive value or QBR brief and validate which claims are supported before sharing.', N'Bring the value/QBR brief, source evidence, unsupported claims removed, strategic asks, and owner for follow-up.'),
        (N'FG-ATS-INVEST', N'WF-INVEST-01', N'ATS-INVEST', N'Today is about assess the strategic and technical case for investment without turning the huddle into a tool demo or a status review.', N'The goal is A strategic and technical investment assessment with dependencies, readiness, risks, and the next governed decision named. AI can assemble evidence and draft options, but ATS judgment stays accountable for strategy, technical accuracy, and next decisions.', N'What technical problem is this investment actually meant to solve?
What would tell you six months from now that it worked?
Which dependency would quietly sink it, and who owns that dependency?', N'Before the session: confirm access to the named tools, bring one real account or technical strategy example, and review the commitment from the prior huddle.', N'What technical outcome does this investment buy that we could not get otherwise?
What is the observable measure that proves it worked?
Which approval or eligibility question are you assuming rather than confirming?', N'Listen for the ATS drifting into eligibility, funding, or approval decisions that belong to other owners, success measures that cannot be observed, deployment paths assumed rather than validated, and handoffs to delivery with no re-engagement trigger.', N'Move from the investment case to the technical evidence it needs and the governed decision that comes next.', N'If tooling is unavailable, map the workflow and human checkpoint manually, then draft the prompt for later testing.', N'Name the investment, the observable success measure, and the approval question you will route to its correct owner rather than answering themselves.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Test one investment case against its technical dependencies, and route one approval question to its real owner.', N'Bring the dependency that would sink it and the owner you routed the question to.'),
        (N'FG-ATS-CBR', N'WF-X-VALUE-01', N'ATS-CBR', N'Today is about prepare the technical contribution for a customer business review without turning the huddle into a tool demo or a status review.', N'The goal is A technical CBR contribution with roadmap points, evidence, risks, decisions, and follow-through. AI can assemble evidence and draft options, but ATS judgment stays accountable for strategy, technical accuracy, and next decisions.', N'What technical progress can you evidence, rather than assert?
Where has progress been slower than the customer expected, and how will you say so?
What decision do you want the review to produce?', N'Before the session: confirm access to the named tools, bring one real account or technical strategy example, and review the commitment from the prior huddle.', N'Which technical claim in your contribution can you evidence today?
How will you present the area where progress was slower than promised?
What decision should this review produce, and who makes it?', N'Listen for progress narrated rather than evidenced, slow areas omitted rather than addressed, roadmap statements that commit the product group, and reviews that end without a decision. Also listen for a technical contribution disconnected from the business outcome the customer cares about.', N'Move from the technical contribution to the decisions it should trigger, and the evidence each decision requires.', N'If tooling is unavailable, map the workflow and human checkpoint manually, then draft the prompt for later testing.', N'Name the technical claim you will evidence before the review, and the slow area you will address openly rather than omit.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Evidence one technical claim before your next customer review, and decide how you will address the slowest area.', N'Bring the evidenced claim and how you handled the area that is behind.'),
        (N'FG-ATS-HEALTH', N'WF-X-HEALTH-01', N'ATS-HEALTH', N'Today is about assess technical health and prioritize risk response without turning the huddle into a tool demo or a status review.', N'The goal is A prioritized technical risk response with source signals, owner, intervention, and checkpoint. AI can assemble evidence and draft options, but ATS judgment stays accountable for strategy, technical accuracy, and next decisions.', N'Which technical risk have you known about for weeks without acting on?
What is stopping you: evidence, ownership, or the conversation itself?
Which risk would the customer say is most urgent, and does it match yours?', N'Before the session: confirm access to the named tools, bring one real account or technical strategy example, and review the commitment from the prior huddle.', N'Which risk is most likely to become an escalation, and what is the earliest signal?
Who owns the intervention, and have they agreed to it?
What would you tell the customer today if you had to raise this now?', N'Listen for risks ranked by score rather than by consequence, interventions with no named owner, escalation thresholds that were never defined, and risks the team has normalized because they have lived with them. Also listen for signals from conversations that never made it into the system data.', N'Move from the ranked risk view to one intervention with an owner, a date, and an escalation threshold.', N'If tooling is unavailable, map the workflow and human checkpoint manually, then draft the prompt for later testing.', N'Name the top technical risk, the intervention, the owner who has agreed to it, and the threshold that would trigger escalation.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Take one technical risk to its owner this week with the intervention and the escalation threshold.', N'Bring the risk, the owner who accepted it, and the threshold you agreed.'),
        (N'FG-SE-INVEST', N'WF-INVEST-01', N'SE-INVEST', N'Investment-funded proof work needs scope, success measures, failure-mode awareness, and handoff boundaries before execution begins.', N'SE owns the technical clarity, not eligibility, policy, commercial, or approval decisions.
Success measures must be observable.
Delivery handoff should state what is decided, what remains open, and when SE must be re-engaged.', N'What technical problem is the investment meant to prove or unblock?
Which success measure is observable enough?
What failure mode would make the investment underdeliver?', N'Bring a proposed investment-funded proof, workshop, PoC, or scoped engagement and the current technical assumptions.', N'Which technical scope boundary matters most?
Which success measure proves the investment helped?
What failure mode or handoff gap needs to be closed before review?', N'Listen for eligibility or approval decisions implied by the SE, vague proof measures, hidden open questions, and delivery handoffs without re-engagement triggers.', N'Move from investment idea to bounded technical proof package.', N'If live data is inappropriate, use a sanitized case and do not infer eligibility, funding, policy, or approval status.', N'Commit to to one scoped technical proof artifact, success measure, or delivery handoff update.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Define what one investment-funded proof must demonstrate, in measures someone else could verify.', N'Bring the success measures and the failure mode you named.'),
        (N'FG-CE-INVEST', N'WF-INVEST-01', N'CE-INVEST', N'Investment succeeds on role clarity, evidence, and clean handoffs. Today is about the commercial and policy link in that chain.', N'Eligibility, funding, exception, and approval remain human decisions. The CE contribution is to surface commercial and policy dependencies, cite authoritative guidance, and route questions to the right owner.', N'Which commercial dependency would slow this investment later? Which decision is genuinely yours? Which question must be routed to an authoritative owner?', N'Before the session: bring one proposed or in-flight investment, customer agreement context, current policy question, and the known owner or approver.', N'Which activity helps clarify the commercial or policy dependency? What would make the output safe to use? Where must a human owner decide?', N'Listen for: eligibility, funding, or approval implied rather than decided; exception ownership unclear; handoffs without named owners; and questions that need authoritative guidance.', N'Move from the investment lifecycle to the CE-owned dependency and the next governed action.', N'Use a sanitized scenario. Do not use live customer data or infer eligibility, approval, exception, or funding status.', N'Map one investment dependency to the authoritative question, owner, and next human decision.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Map the approval dependencies for one investment and find where it is actually waiting.', N'Bring the dependency map and the blocker you identified.'),
        (N'FG-CSA-INVEST', N'WF-INVEST-01', N'CSA-INVEST', N'Investment succeeds on role clarity, evidence and clean handoffs. Today is about your part of that chain.', N'Every role owns one link. The chain breaks at the handoff.
Eligibility, funding and approval are human decisions. AI assembles the evidence.
An investment request without named open questions hides them rather than resolving them.', N'Where could investment-funded scope become undeliverable?
Which prerequisite, dependency, or owner must be confirmed before delivery starts?
What technical outcome evidence will be needed later?', N'Before the session: bring one proposed or approved investment-funded scope, known technical dependencies, and the delivery checkpoints you would want confirmed.', N'Which investment activity is closest to your real delivery responsibility?
What status or milestone data must be verified before acting?
Where could handoff, prerequisite, or ownership failure become customer-visible?', N'Through the CSA lens, listen for: funding or approval inferred from summaries; delivery status not checked against the authoritative record; unowned prerequisites; and technical outcomes that cannot be measured later.', N'Move from the investment lifecycle to the CSA''s delivery-readiness or outcome-evidence action on a live or sanitized case.', N'Use a sanitized scenario. Do not use live customer data or infer eligibility, approval or funding status.', N'Name one investment delivery-readiness check or outcome-evidence action and its owner.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Validate delivery readiness for one investment and name the dependency most likely to slip.', N'Bring the readiness assessment and the dependency you flagged.'),
        (N'FG-CSAM-INVEST', N'WF-INVEST-01', N'CSAM-INVEST', N'Customer investment should be governed through the success plan, not treated as a separate administrative process.', N'Investment execution needs owners, milestones, handoffs, risk tracking and value evidence. The CSAM governs the operating rhythm and realization story.', N'Is the investment on this account connected to the success plan, or running beside it?
Who owns delivery, and when did you last confirm status with them rather than assume it?
What evidence would the realization review need that you do not have yet?', N'Before the session: bring one active or proposed customer investment, scope, milestone list or execution question.', N'How does this investment show up in the success plan?
Which delivery status did you confirm rather than assume?
What evidence will the realization review need, and who is producing it?', N'Listen for investment running as a parallel process rather than part of the success plan, delivery status inferred from silence, realization evidence identified only when the review is booked, and the CSAM answering eligibility or approval questions that belong elsewhere.', N'Move from the investment rhythm to the one checkpoint you will run this month and the evidence it produces.', N'If the tool or data source is unavailable, map the current workflow manually, name the trusted sources and draft the prompt plus human checkpoint for later testing.', N'Name the investment checkpoint you will run, the delivery status you will confirm rather than assume, and the realization evidence you will start collecting.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Run one investment checkpoint and confirm a delivery status rather than assuming it.', N'Bring the status you confirmed and how it differed from what you assumed.'),
        (N'FG-ATS-PARTNER', N'WF-X-ORCH-01', N'ATS-PARTNER', N'Today is about align partner and specialist support to technical priorities without turning the huddle into a tool demo or a status review.', N'The goal is A partner and specialist alignment plan with feature gaps, owners, timing, and next decision. AI can assemble evidence and draft options, but ATS judgment stays accountable for strategy, technical accuracy, and next decisions.', N'Where is technical feature the constraint, rather than time or priority?
When you last brought in a specialist, did it change the outcome?
What would a partner need from you to arrive useful rather than catching up?', N'Before the session: confirm access to the named tools, bring one real account or technical strategy example, and review the commitment from the prior huddle.', N'Is the gap feature, capacity, or clarity? They need different answers.
What exactly would you ask this partner or specialist to do?
What will you send them so they arrive useful rather than catching up?', N'Listen for support requested by habit rather than by need, asks vague enough that anyone could decline them politely, briefings promised verbally and never sent, and customer-sensitive detail heading to an external partner without a classification step.', N'Move from the feature gap to one specific, dated ask with the briefing that makes it answerable.', N'If tooling is unavailable, map the workflow and human checkpoint manually, then draft the prompt for later testing.', N'Name the feature gap, the specific ask you will send, who receives it, and whether that recipient is internal or external.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Write one specific partner or specialist ask and send the briefing that makes it answerable.', N'Bring the ask, the briefing, and whether the recipient was internal or external.'),
        (N'FG-SSP-INVEST', N'WF-INVEST-01', N'SSP-INVEST', N'Investment requests slow down when inputs, owners, or open questions are hidden. Today is about readiness.', N'Separate facts from assumptions. Name confirmed inputs, gaps, contributors, policy/process questions, and next governed action.', N'Which request input is missing? Who owns it? What should not be represented as approved?', N'Before the session: bring one live solution pursuit, solution play, lead list, opportunity, or investment case relevant to this huddle; confirm tool access; review last commitment and evidence.', N'What request input is missing? Who owns it? What decision must remain human?', N'Listen for eligibility or funding implied rather than confirmed, hidden open questions, and contributor inputs without owners.', N'Move from request readiness to next governed action.', N'Use a sanitized scenario if live investment data should not be used.', N'Name the next governed investment action, owner, and evidence needed.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Check one investment request against what a complete submission needs before you submit it.', N'Bring what was missing and where the request sits now.'),
        (N'FG-ALL-USECASE', N'WF-X-USECASE-01', N'ALL-USECASE', N'This huddle has no pre-written workflow. The team chooses one, which means the value depends entirely on picking a workflow people actually run. Anchor the session in real work and trusted context before anyone opens a tool.', N'The workflow must be recurring, not a one-off.
Someone in the room must actually own it.
A specific recent example beats a general description.
If the team cannot name a real example, the workflow is too abstract to work on.', N'What workflow are we improving today?
What triggers it, and how often does it run?
What inputs, constraints, and approvals shape it?
Whose work is it, and who else depends on the output?', N'Bring one recurring workflow you personally run and one recent example of it, including what made that run harder than it needed to be.', N'Where in this workflow is effort or quality lost today?
What is the smallest step AI could assist, rather than the whole workflow?
What must a person verify before the output is used?
What would a one-week version of this experiment look like?', N'Listen for scope that is too broad to test in a week, inputs the person cannot actually access, an output nobody would notice if it were wrong, and enthusiasm for a tool without a workflow behind it. Also listen for the opposite problem: a step so small that automating it changes nothing.', N'Move from the friction people named to one specific assistable step, then from that step to a single bounded experiment with an owner.', N'If a tool or data source is unavailable, map the workflow on paper and design the experiment for later execution. Use a hypothetical process shape if needed, but do not invent business facts, customer detail, or system behavior.', N'Name the workflow you chose, the one step you will test, the human checkpoint you will keep, and the evidence you will bring back. If you cannot name an owner or a date, the experiment is not real yet; shrink it until it is.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'What will you test this week? State the input, the action, the output, who reviews it, and what would tell you to stop.', N'Bring the actual output from your experiment, whether it worked or not. A failed experiment with evidence is more useful to the group than a success without it.'),
        (N'FG-ALL-DEAL', N'WF-X-DEAL-01', N'ALL-DEAL', N'Deal making features live inside Sales Agent. There is no separate agent to select: when you ask Sales a deal-related question, those features answer. This session is not about learning to run deals. It is about being able to find deal facts for your own accounts, whatever your role, instead of waiting for someone to send them to you.', N'Deal Agent is a skill inside Sales Chat, reached by picking the Sales agent in Microsoft 365 Copilot. There is nothing separate to install or select.
Its primary motion is renewals, specifically EA and MCA-E. That is where it is strongest.
The trigger is specificity. A TPID, agreement number, or enrollment number returns real data; a vague account reference returns a generic answer.
Keep one chat thread per deal. Mixing several deals into one thread confuses the context and makes the history hard to audit.
Looking up deal facts is open to every role. Commercial decisions, approvals, and material amendments are not.', N'When did you last need agreement, licensing, or renewal information and have to ask someone for it?
How long did that take, and what did you do while waiting?
What have you assumed about a customer''s entitlements that you have never actually verified?', N'Bring one real account you work on, and if you have it, an agreement number, enrollment number, or TPID. If you do not have an identifier, bring the account name and we will find one in the session.', N'What did the lookup return that you did not already know?
What did you previously assume about this customer''s estate that turned out to be wrong or unverified?
Where does this stop being your call and become the deal owner''s?', N'Listen for vague prompts producing vague answers, which is the most common reason people conclude deal making does not work. Listen for a first response being treated as final on a complex deal, when the guidance is to re-run and verify against current data. Listen for several unrelated deals being worked in one chat thread. Listen for someone treating a retrieved figure as approved pricing or a commitment, or stepping past retrieval into structuring a deal that belongs to the AE or Commercial Executive. Also listen for the opposite: someone escalating a question they could now answer themselves.', N'Move from the lookup you ran to the single fact that changes how you would open your next conversation with that customer.', N'If Sales Agent access is unavailable or a lookup returns nothing, work from an account you know and list what you would need to verify before the next customer conversation, then name who currently holds each answer. Do not guess at entitlements, pricing, or discount levels.', N'Name the account you looked up, the one fact that surprised you, and one question you previously would have escalated but can now answer yourself. If nothing was new, pick a less familiar account before the next session.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'What will you do this week? Look up one account before a real customer conversation and use one retrieved fact in that conversation.', N'Bring the prompt you used, what came back, and whether it changed how the conversation went. If the lookup returned nothing useful, bring the prompt so the group can sharpen it.')
    ) v([ExternalId], [TopicExternalId], [PlacementExternalId], [SessionIntroduction], [KeyTalkingPoints], [DiscussionQuestions], [PreparationChecklist], [FacilitatorQuestions], [ListenFor], [SuggestedTransitions], [FallbackGuidance], [WrapUpGuidance], [ReflectPrompt], [CommitPrompt], [BringBackEvidence])
), src AS (
    SELECT raw.*, t.Id AS [HuddleTopicId], p.Id AS [HuddlePlacementId]
    FROM raw
    INNER JOIN dbo.HuddleTopics AS t ON t.[ExternalId] = raw.[TopicExternalId]
    INNER JOIN dbo.HuddlePlacements AS p ON p.[ExternalId] = raw.[PlacementExternalId]
)
MERGE dbo.HuddleFacilitatorGuides AS tgt
USING src ON tgt.[ExternalId] = src.[ExternalId]
WHEN MATCHED THEN UPDATE SET
        tgt.[HuddleTopicId] = src.[HuddleTopicId],
        tgt.[HuddlePlacementId] = src.[HuddlePlacementId],
        tgt.[SessionIntroduction] = src.[SessionIntroduction],
        tgt.[KeyTalkingPoints] = src.[KeyTalkingPoints],
        tgt.[DiscussionQuestions] = src.[DiscussionQuestions],
        tgt.[PreparationChecklist] = src.[PreparationChecklist],
        tgt.[FacilitatorQuestions] = src.[FacilitatorQuestions],
        tgt.[ListenFor] = src.[ListenFor],
        tgt.[SuggestedTransitions] = src.[SuggestedTransitions],
        tgt.[FallbackGuidance] = src.[FallbackGuidance],
        tgt.[WrapUpGuidance] = src.[WrapUpGuidance],
        tgt.[ReflectPrompt] = src.[ReflectPrompt],
        tgt.[CommitPrompt] = src.[CommitPrompt],
        tgt.[BringBackEvidence] = src.[BringBackEvidence],
        tgt.[UpdatedAtUtc] = SYSUTCDATETIME()
WHEN NOT MATCHED BY TARGET THEN INSERT ([ExternalId], [HuddleTopicId], [HuddlePlacementId], [SessionIntroduction], [KeyTalkingPoints], [DiscussionQuestions], [PreparationChecklist], [FacilitatorQuestions], [ListenFor], [SuggestedTransitions], [FallbackGuidance], [WrapUpGuidance], [ReflectPrompt], [CommitPrompt], [BringBackEvidence], [CreatedAtUtc])
    VALUES (src.[ExternalId], src.[HuddleTopicId], src.[HuddlePlacementId], src.[SessionIntroduction], src.[KeyTalkingPoints], src.[DiscussionQuestions], src.[PreparationChecklist], src.[FacilitatorQuestions], src.[ListenFor], src.[SuggestedTransitions], src.[FallbackGuidance], src.[WrapUpGuidance], src.[ReflectPrompt], src.[CommitPrompt], src.[BringBackEvidence], SYSUTCDATETIME());
;WITH raw AS (
    SELECT * FROM (VALUES
        (N'FG-AE-ORIENT', N'WF-ORIENT-01', N'AE-ORIENT', N'This session sets the operating model for the AE path. The point is not tool fluency for its own sake; it is better account, pipeline, deal, and customer-conversation execution with human judgment visible.', N'The huddle is workflow-first. Every session uses real AE work, a practical AI-supported practice, and a human checkpoint. AI can assemble evidence, summarize, draft, and monitor; the AE owns judgment, customer trust, commitments, and next decisions.', N'Which part of your week is assembling information rather than deciding anything?
Where do you already use AI, and where have you avoided it?
What would you need to see before you trusted an AI-drafted account, pipeline, or customer-facing output?', N'Before the session: confirm access to the tools named for this path, and come ready to describe the work you repeat most weeks. No prior AI experience is needed for this session.', N'Which account, pipeline, or customer-facing work do you repeat every week without thinking of it as a workflow?
Which of those steps is assembling information rather than making a decision?
Where must the AE judgment stay human no matter how good the output gets?', N'Listen for unvoiced scepticism, access blockers stated as disinterest, the assumption that this is a tool rollout, and people who describe only their exceptional work rather than the work they repeat. The recurring, unglamorous tasks are the ones worth mapping.', N'Move from how the motion works to the recurring work each person will map with the discovery prompt this week.', N'If tool access is not confirmed, still run the discovery conversation and record access blockers separately from interest. The discovery prompt can be run in whichever tool the person already has.', N'Close by pointing the team to the resources for next week''s topic and to the workflow-discovery prompt below. Week 1 is for finding the recurring work worth automating.', N'Which part of your week had you never thought of as a workflow until now? What would have to be true before you trusted AI with it?', N'Run this in Microsoft 365 Copilot, Cowork, or Scout before the next huddle, then bring the result to the session:

"I am an Account Executive at Microsoft and I want to find the recurring work in my week that AI could take on.
1. First, look at my calendar, mail and Teams activity from the last four weeks and tell me what you can see about where my time actually goes. If you cannot access that data, say so and move to step 2 rather than guessing.
2. Then ask me up to five short questions, one at a time, to cover the work that never shows up in a calendar or an inbox.
3. Then list the five things I do most often. For each one give an estimate of the time it costs me per month, whether it is best handled as a saved prompt, a reusable skill, a scheduled automation or an existing agent, and the one judgment that must stay mine.
4. Rank them by time returned and tell me which one to start with."', N'Bring the ranked list of the five things you repeat most, which of them looked like a prompt, skill, automation, or agent fit, and any AI experience from the week, including anything that did not work.'),
        (N'FG-AE-PLAN', N'WF-X-PLAN-01', N'AE-PLAN', N'Account planning fails when it becomes an inventory. Today is about a short operating plan that helps you decide where attention goes this week.', N'Prioritization requires saying no. AI can assemble customer, pipeline, renewal, whitespace, partner, and investment signals. The AE decides which account deserves action and why.', N'Which accounts get your attention by habit rather than evidence? Where is the account plan missing a decision? What signal would change your priority list?', N'Before the session: bring one territory or account list and one account where the next action is unclear.', N'Which account deserves attention that it is not getting? Which account gets attention mostly by habit? What evidence would change your top three?', N'Listen for planning as annual documentation, prioritization by revenue alone, unclear next actions, missing role coverage, and customer priorities not connected to pipeline.', N'Move from account list discussion to one AE selecting a top account and naming the next action.', N'If tools are unavailable, run the prioritization manually and record the prompt or Scout/Cowork skill candidate for later.', N'Name the top accounts you will act on and the evidence behind the priority.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Use AI to build or refine one account priority view, then choose one next action you will actually take.', N'Bring the prioritized account list, source signals, the action chosen, and any assumptions you rejected.'),
        (N'FG-AE-PIPE-1', N'WF-X-PIPE-01', N'AE-PIPE-1', N'Today is about restoring trust in the pipeline signal before it becomes a forecast argument.', N'Bad data creates bad inspection. Stage, close date, next step, customer engagement, and partner attach should reflect reality. AI can flag issues; the AE verifies and decides the correction.', N'Where does your pipeline data most often mislead you? Which field do you trust least? Which opportunity would you hesitate to defend in a review?', N'Before the session: bring the scope you normally inspect for pipeline reviews and one opportunity you suspect may be stale or misrepresented.', N'Which opportunity would you not want inspected right now? What field, date, or next step might be telling the wrong story? What correction would change the forecast conversation?', N'Listen for manual reconciliation, stale dates, close-date optimism, missing customer engagement, and records corrected only right before reviews.', N'Move from aggregate gap to one opportunity that needs correction or verification.', N'If certified reports are unavailable, map the inspection routine and identify where evidence should come from.', N'Name one opportunity record to correct, verify, or escalate for missing evidence.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Run one pipeline signal-quality check and correct or flag one material issue.', N'Bring the before/after record state or issue list, the source signal, and the decision you made as the owner.'),
        (N'FG-AE-PIPE-2', N'WF-X-PIPE-01', N'AE-PIPE-2', N'A forecast narrative explains what changed, what is at risk, and what decision is needed. Today is about building that story from evidence.', N'The number alone does not create confidence. Movement, risk, timing, and inspection questions need to be visible. AI can draft the story, but the AE owns the commitment and caveats.', N'What changed since the last review? Which commit has the weakest evidence? What question from your manager would be hardest to answer?', N'Before the session: bring the current forecast scope and the report or meeting notes you use for weekly inspection.', N'What changed since last week? Which commit carries the most risk? What would your manager ask that the current narrative cannot answer?', N'Listen for forecast narrative built from memory, risk without evidence, unclear inspection questions, and confusion between confidence and wishful thinking.', N'Move from report output to the narrative the AE would actually use in a forecast review.', N'If data access is unavailable, build the narrative structure and mark which claims need certified data.', N'Name one forecast risk and the inspection question that will resolve it.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Draft one forecast narrative for your scope and use it in your next inspection or manager discussion.', N'Bring the narrative, supporting metrics, unresolved questions, and what you changed after human review.'),
        (N'FG-AE-OPP', N'WF-X-OPP-01', N'AE-OPP', N'The next opportunity is often already visible in customer signals. Today is about finding and testing those signals without creating pipeline noise.', N'Whitespace is not just a product gap. A qualified opportunity has a trigger, stakeholder, business problem, next action, and evidence. AI can surface signals; the AE tests whether they are real.', N'Where did your last real opportunity come from? What makes a signal qualified rather than hopeful? Where might you be missing a signal because it sits outside MSX?', N'Before the session: bring one account with recent meetings, engagement, or whitespace that might become an opportunity.', N'Which signal looks promising but not yet qualified? What evidence would make it real? What customer action would test the hypothesis?', N'Listen for opportunities created to fill coverage, whitespace treated as product absence, duplicate opportunities, and signals without a named stakeholder or trigger.', N'Move from signal discovery to one opportunity hypothesis and the first outreach or discovery action.', N'If tooling is unavailable, work from one account’s known context and draft the prompt to run later.', N'Commit to to testing one opportunity signal with a real customer or account-team action.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Qualify one opportunity hypothesis and document the trigger, evidence, next action, and uncertainty.', N'Bring the opportunity hypothesis, evidence, outreach or discovery step, and whether it became qualified or was rejected.'),
        (N'FG-AE-CONV', N'WF-X-CONV-01', N'AE-CONV', N'Customer conversations are where decisions move. Today is about preparing the position, evidence, objections, and ask before the meeting starts.', N'A brief is not a recap. It should state the intended outcome, customer context, evidence, open questions, likely objections, and the ask. The AE validates tone and relationship nuance.', N'What do you often walk into a meeting still not knowing? What would change if the ask were explicit before the meeting? Which claim would need validation before customer use?', N'Before the session: bring one upcoming customer meeting, the desired decision, and any approved source materials you want to use.', N'What decision should the meeting move? What claim must be validated? What objection is likely but uncomfortable to prepare for?', N'Listen for recaps instead of positions, meetings with no intended outcome, generic value language, unsupported claims, and missing fallback asks.', N'Move from preparation concept to one live meeting brief and the ask the AE will use.', N'If tools are unavailable, build the brief skeleton manually and identify source gaps.', N'Pick one customer meeting and names the primary ask and fallback ask.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Prepare one customer conversation brief and validate the claims before use.', N'Bring the brief, source signals, validated or removed claims, primary ask, fallback ask, and meeting outcome if available.'),
        (N'FG-AE-DEAL', N'WF-X-DEAL-01', N'AE-DEAL', N'Strategic deals stall when the next decision, blocker, or owner is unnamed. Today is about making the deal inspectable.', N'A close date is not a plan. Exit criteria, approvals, commercial dependencies, stakeholder coverage, and customer actions determine whether the deal can move. AI can organize the deal picture; the AE routes decisions to the right owners.', N'What is your deal really waiting on? Which approval, customer action, or role gap is not yet explicit? What should not be decided by AI?', N'Before the session: bring one live opportunity, the current stage, and the next decision you believe is needed.', N'What is the next decision, not the next task? Which blocker has no owner? Which commercial, technical, or partner decision needs another role?', N'Listen for close date as proxy for plan, approval paths discovered late, role gaps, unsupported deal assumptions, and AI outputs that overstep CE or SME authority.', N'Move from deal summary to the next decision and owner map.', N'If systems are unavailable, whiteboard the decision path, blockers, and accountable owners.', N'Name the next decision on one live deal and the owner for every blocker.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Inspect one strategic deal and route at least one blocker or decision to the right owner.', N'Bring the deal inspection, blocker-owner map, routed ask, and what changed in the deal plan.'),
        (N'FG-AE-RENEW', N'WF-X-RENEW-01', N'AE-RENEW', N'Renewal risk is usually visible before the renewal conversation. Today is about finding it while there is still time to act.', N'Renewal health depends on value evidence, usage or consumption signals, relationship recency, commercial readiness, and expansion logic. AI can surface patterns; the AE validates intent and next action.', N'Which upcoming renewal has the weakest value evidence? What expansion hypothesis is already visible? Where do you need CSAM, CSA, CE, or SSP input?', N'Before the session: bring one account renewing in the next planning window and the evidence you currently use to judge risk.', N'What is the largest renewal risk? What value evidence would the customer recognize? Which expansion signal is supported by usage, consumption, or customer priority?', N'Listen for renewals treated as admin, value evidence built too late, expansion detached from customer outcomes, and unclear CSAM/CSA/CE ownership.', N'Move from renewal principles to one account and the action that changes risk this week.', N'If data is unavailable, work from known context and list evidence gaps to close.', N'Name one renewal risk, one value evidence gap, and one expansion hypothesis.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Assess one upcoming renewal and take one action that reduces risk or strengthens value evidence.', N'Bring the renewal assessment, risk, evidence gap, expansion hypothesis, and the owner for the next action.'),
        (N'FG-ATS-ORIENT', N'WF-ORIENT-01', N'ATS-ORIENT', N'This session explains how the huddle motion works and how ATS team members should test AI on real technical strategy work.', N'Huddles are workflow-led, not tool demos. Every session ends with one experiment. Human judgment stays explicit.', N'Which part of your week is assembling information rather than deciding anything?
Where do you already use AI, and where have you avoided it?
What would you need to see before you trusted an AI-drafted technical strategy output?', N'Before the session: confirm access to the tools named for this path, and come ready to describe the work you repeat most weeks. No prior AI experience is needed for this session.', N'Which technical strategy work do you repeat every week without thinking of it as a workflow?
Which of those steps is assembling information rather than making a decision?
Where must the ATS judgment stay human no matter how good the output gets?', N'Listen for unvoiced scepticism, access blockers stated as disinterest, the assumption that this is a tool rollout, and people who describe only their exceptional work rather than the work they repeat. The recurring, unglamorous tasks are the ones worth mapping.', N'Move from how the motion works to the recurring work each person will map with the discovery prompt this week.', N'If tool access is not confirmed, still run the discovery conversation and record access blockers separately from interest. The discovery prompt can be run in whichever tool the person already has.', N'Close by pointing the team to the resources for next week''s topic and to the workflow-discovery prompt below. Week 1 is for finding the recurring work worth automating.', N'Which part of your week had you never thought of as a workflow until now? What would have to be true before you trusted AI with it?', N'Run this in Microsoft 365 Copilot, Cowork, or Scout before the next huddle, then bring the result to the session:

"I am an Account Technology Strategist at Microsoft and I want to find the recurring work in my week that AI could take on.
1. First, look at my calendar, mail and Teams activity from the last four weeks and tell me what you can see about where my time actually goes. If you cannot access that data, say so and move to step 2 rather than guessing.
2. Then ask me up to five short questions, one at a time, to cover the work that never shows up in a calendar or an inbox.
3. Then list the five things I do most often. For each one give an estimate of the time it costs me per month, whether it is best handled as a saved prompt, a reusable skill, a scheduled automation or an existing agent, and the one judgment that must stay mine.
4. Rank them by time returned and tell me which one to start with."', N'Bring the ranked list of the five things you repeat most, which of them looked like a prompt, skill, automation, or agent fit, and any AI experience from the week, including anything that did not work.'),
        (N'FG-ATS-INTEL', N'WF-X-PLAN-01', N'ATS-INTEL', N'Today is about build an account intelligence and meeting prep brief without turning the huddle into a tool demo or a status review.', N'The goal is An account intelligence brief with technical risks, workload signals, stakeholder context, and next actions. AI can assemble evidence and draft options, but ATS judgment stays accountable for strategy, technical accuracy, and next decisions.', N'Which account are you least confident you could brief someone on right now?
Where does your current account picture come from, and how old is it?
What technical signal would change your priorities this week if you knew it today?', N'Before the session: confirm access to the named tools, bring one real account or technical strategy example, and review the commitment from the prior huddle.', N'What is in your account brief that you could not source if challenged?
Which signal in the brief actually changes what you do next week?
What is missing that you only notice once it is written down?', N'Listen for briefs assembled from memory rather than systems, KPI figures quoted without their definition or date, technical risks with no named owner, and stakeholder context that is a year old. Also listen for the brief becoming an end in itself rather than driving a decision.', N'Move from the assembled account picture to the single signal that should change this week''s priorities.', N'If tooling is unavailable, map the workflow and human checkpoint manually, then draft the prompt for later testing.', N'Name the account you will brief, the signal you will chase down, and the source you will use to close it. If the brief will not change a decision, pick a different account.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Build an account intelligence brief for one account, and chase down the one signal you could not source.', N'Bring the brief and the signal you had to verify manually.'),
        (N'FG-ATS-NARR', N'WF-X-CONV-01', N'ATS-NARR', N'Today is about assemble an executive technical customer narrative without turning the huddle into a tool demo or a status review.', N'The goal is An executive-ready technical narrative with sourced claims, proof points, decision questions, and a technical ask. AI can assemble evidence and draft options, but ATS judgment stays accountable for strategy, technical accuracy, and next decisions.', N'When did an executive last stop you to ask what something meant?
Which part of your technical story do you find hardest to say without jargon?
What decision do you actually need from the executive, and have you ever asked for it directly?', N'Before the session: confirm access to the named tools, bring one real account or technical strategy example, and review the commitment from the prior huddle.', N'Read your opening line aloud. Would a CFO know what you meant?
Which claim in your narrative rests on a proof point you do not have?
What are you asking the executive to decide, stated in one sentence?', N'Listen for architecture described rather than translated, value asserted without evidence, narratives that end without an ask, and jargon that survived because nobody in the room questioned it. Also listen for a narrative aimed at the technical stakeholder while claiming to target the executive.', N'Move from the technical story to the one decision you want the executive to make, and the proof they need to make it.', N'If tooling is unavailable, map the workflow and human checkpoint manually, then draft the prompt for later testing.', N'Name the executive audience, the single decision you will ask for, and the proof point they still need. If there is no ask, the narrative is not ready.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Rewrite one technical narrative for an executive audience, and state the single decision you are asking for.', N'Bring the narrative, the ask, and the proof point you still need.'),
        (N'FG-ATS-WORKLOAD', N'WF-X-PLAN-01', N'ATS-WORKLOAD', N'Today is about prioritize ai and azure workloads by readiness and impact without turning the huddle into a tool demo or a status review.', N'The goal is A ranked workload view with readiness, impact, evidence, owner, and validation gaps. AI can assemble evidence and draft options, but ATS judgment stays accountable for strategy, technical accuracy, and next decisions.', N'Which workload are you spending time on because it is genuinely the priority, and which because it has momentum?
What readiness evidence would change your ranking?
Which workload would you drop if you had to drop one this quarter?', N'Before the session: confirm access to the named tools, bring one real account or technical strategy example, and review the commitment from the prior huddle.', N'What evidence supports your top-ranked workload, beyond it feeling important?
Which workload is ranked high because of readiness, and which because of upside?
What would have to be true for your ranking to be wrong?', N'Listen for rankings driven by the loudest stakeholder, readiness assumed rather than checked, upside estimated with no basis, and dependencies discovered after commitment. Also listen for a list that ranks everything and therefore prioritizes nothing.', N'Move from the ranked list to the one workload you will commit technical time to, and what evidence you still need.', N'If tooling is unavailable, map the workflow and human checkpoint manually, then draft the prompt for later testing.', N'Name the workload you are committing technical time to this week, the readiness evidence still missing, and who owns closing that gap.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Rank your workloads by readiness and impact, then commit technical time to the top one.', N'Bring the ranking, the workload you chose, and the readiness evidence still missing.'),
        (N'FG-ATS-TECH', N'WF-X-ARCH-01', N'ATS-TECH', N'Today is about develop a technical strategy and decision trajectory without turning the huddle into a tool demo or a status review.', N'The goal is A technical trajectory with priority bets, proof needs, owners, risks, milestones, and open decisions. AI can assemble evidence and draft options, but ATS judgment stays accountable for strategy, technical accuracy, and next decisions.', N'What is the next technical decision this customer has to make, and when?
Which of your technical bets is least supported by evidence?
What would have to be true for the customer to commit to the direction you are recommending?', N'Before the session: confirm access to the named tools, bring one real account or technical strategy example, and review the commitment from the prior huddle.', N'What is the next decision in the trajectory, and who makes it?
Which bet would you abandon first if evidence went against it?
What proof does the customer need before they will commit, and do you have a path to producing it?', N'Listen for a strategy that is a destination without a sequence, bets with no falsification condition, proof needs identified after the customer already asked, and milestones with no owner. Also listen for technical direction set without the customer''s own objectives in the room.', N'Move from the technical direction to the next decision it requires, with an owner and the evidence that unblocks it.', N'If tooling is unavailable, map the workflow and human checkpoint manually, then draft the prompt for later testing.', N'Name the next technical decision, its owner, the date it must happen by, and the proof the customer needs to make it.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Name the next technical decision on one account, its owner, and the date it must happen by.', N'Bring the decision, the owner who agreed to it, and the proof the customer needs.'),
        (N'FG-ATS-EBC', N'WF-X-CONV-01', N'ATS-EBC', N'Today is about design an executive briefing experience without turning the huddle into a tool demo or a status review.', N'The goal is An EBC plan with desired decisions, participants, evidence, preparation milestones, and follow-through ownership. AI can assemble evidence and draft options, but ATS judgment stays accountable for strategy, technical accuracy, and next decisions.', N'What is the one thing the customer should leave the briefing believing?
Who in the room can actually approve the next step?
What would make this briefing worth their time rather than ours?', N'Before the session: confirm access to the named tools, bring one real account or technical strategy example, and review the commitment from the prior huddle.', N'What will the customer do differently after this briefing?
Who in the room can approve that, and are they invited?
Which part of the agenda serves us rather than them?', N'Listen for agendas built around what we want to present, attendee lists without a decision maker, briefings with no ask, and content density that leaves no room for the customer to talk. Also listen for an experience designed for the meeting rather than for what happens after it.', N'Move from the briefing design to the single decision it is meant to produce and who must be present for that.', N'If tooling is unavailable, map the workflow and human checkpoint manually, then draft the prompt for later testing.', N'Name the briefing, the decision it should produce, and the one person who must be in the room for that decision to be possible.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Design one executive briefing around a single decision, and confirm the person who can make it will be there.', N'Bring the decision the briefing targets and confirmation the approver is invited.'),
        (N'FG-ATS-TALK', N'WF-X-CONV-01', N'ATS-TALK', N'Today is about adjust the technical talk track from customer signals without turning the huddle into a tool demo or a status review.', N'The goal is A signal-adjusted talk track with opening language, questions, objections, responses, and human review flags. AI can assemble evidence and draft options, but ATS judgment stays accountable for strategy, technical accuracy, and next decisions.', N'What did the customer say recently that should change how you talk about this?
Where is your current talk track still answering last quarter''s objection?
What signal are you choosing to ignore because it is inconvenient?', N'Before the session: confirm access to the named tools, bring one real account or technical strategy example, and review the commitment from the prior huddle.', N'What specifically did the customer say, and what did you infer from it?
Which part of your talk track is now answering a question they stopped asking?
What would you change if you took their last objection at face value?', N'Listen for signals interpreted to confirm what we already planned, talk tracks updated in wording but not in substance, and customer silence read as agreement. Also listen for adjustments based on one conversation with one person treated as the account''s position.', N'Move from the customer signal to the specific line in your talk track that has to change because of it.', N'If tooling is unavailable, map the workflow and human checkpoint manually, then draft the prompt for later testing.', N'Name the customer signal you are acting on and the specific line in your talk track that changes because of it.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Change one line in your talk track based on something a customer actually said this month.', N'Bring the customer signal and the line that changed because of it.'),
        (N'FG-ATS-TEAM', N'WF-X-ORCH-01', N'ATS-TEAM', N'Today is about mobilize the technical v-team around priorities and risks without turning the huddle into a tool demo or a status review.', N'The goal is A technical v-team alignment brief with owners, dependencies, investment signals, checkpoints, and next actions. AI can assemble evidence and draft options, but ATS judgment stays accountable for strategy, technical accuracy, and next decisions.', N'Who on your technical v-team could not state the current priority if asked today?
Which dependency has gone quiet in the last two weeks?
What are you carrying yourself that should belong to someone else?', N'Before the session: confirm access to the named tools, bring one real account or technical strategy example, and review the commitment from the prior huddle.', N'If I asked each v-team member the current priority, would I get the same answer?
Which dependency is at risk, and does its owner know?
What are you doing yourself that is really someone else''s accountability?', N'Listen for priorities that live only in the ATS''s head, owners assigned in a document but never agreed in a conversation, dependencies tracked without dates, and the ATS absorbing work because delegating it feels slower. Also listen for v-team meetings that report status without deciding anything.', N'Move from the coordination picture to one specific ask, to one named person, with a date.', N'If tooling is unavailable, map the workflow and human checkpoint manually, then draft the prompt for later testing.', N'Name one v-team ask you will send this week, to one named person, with a date and what you will supply to make it easy.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Send one specific v-team ask to one named person with a date and what you will supply.', N'Bring the ask you sent and whether it was accepted.'),
        (N'FG-SSP-ORIENT', N'WF-ORIENT-01', N'SSP-ORIENT', N'This session explains the motion and sets expectations for using AI in solution pursuit work.', N'Huddles are workflow-led, not tool demos. Every session ends with one thing to try. Human judgment stays explicit.', N'Which part of your week is assembling information rather than deciding anything?
Where do you already use AI, and where have you avoided it?
What would you need to see before you trusted an AI-drafted solution or pursuit output?', N'Before the session: confirm access to the tools named for this path, and come ready to describe the work you repeat most weeks. No prior AI experience is needed for this session.', N'Which solution or pursuit work do you repeat every week without thinking of it as a workflow?
Which of those steps is assembling information rather than making a decision?
Where must the SSP judgment stay human no matter how good the output gets?', N'Listen for unvoiced scepticism, access blockers stated as disinterest, the assumption that this is a tool rollout, and people who describe only their exceptional work rather than the work they repeat. The recurring, unglamorous tasks are the ones worth mapping.', N'Move from how the motion works to the recurring work each person will map with the discovery prompt this week.', N'If tool access is not confirmed, still run the discovery conversation and record access blockers separately from interest. The discovery prompt can be run in whichever tool the person already has.', N'Close by pointing the team to the resources for next week''s topic and to the workflow-discovery prompt below. Week 1 is for finding the recurring work worth automating.', N'Which part of your week had you never thought of as a workflow until now? What would have to be true before you trusted AI with it?', N'Run this in Microsoft 365 Copilot, Cowork, or Scout before the next huddle, then bring the result to the session:

"I am a Solution Sales Professional at Microsoft and I want to find the recurring work in my week that AI could take on.
1. First, look at my calendar, mail and Teams activity from the last four weeks and tell me what you can see about where my time actually goes. If you cannot access that data, say so and move to step 2 rather than guessing.
2. Then ask me up to five short questions, one at a time, to cover the work that never shows up in a calendar or an inbox.
3. Then list the five things I do most often. For each one give an estimate of the time it costs me per month, whether it is best handled as a saved prompt, a reusable skill, a scheduled automation or an existing agent, and the one judgment that must stay mine.
4. Rank them by time returned and tell me which one to start with."', N'Bring the ranked list of the five things you repeat most, which of them looked like a prompt, skill, automation, or agent fit, and any AI experience from the week, including anything that did not work.'),
        (N'FG-SSP-LEAD', N'WF-X-OPP-01', N'SSP-LEAD', N'Lead and account signals are noisy. Today is about turning them into a focused follow-up plan.', N'Qualification is evidence work. Solution relevance, owner, message, consent, and next action must be explicit.', N'Which lead or signal deserves attention first? What evidence makes it real? Who owns the next action?', N'Before the session: bring one live solution pursuit, solution play, lead list, opportunity, or investment case relevant to this huddle; confirm tool access; review last commitment and evidence.', N'Which lead or account signal deserves follow-up first? What evidence supports solution relevance?', N'Listen for undifferentiated lead lists, vague ownership, weak message fit, and missing consent/context.', N'Move from noisy signals to one prioritized follow-up plan.', N'If systems are unavailable, manually rank one lead list and draft the prompt for later testing.', N'Commit to to ranking one lead or prospect list and owning the top next action.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Turn your top-priority lead into an actual first contact this week.', N'Bring the message you sent and whether the signal was worth following.'),
        (N'FG-SSP-PLAN', N'WF-X-PLAN-01', N'SSP-PLAN', N'A solution-selling plan is useful only if it changes pursuit execution. Today is about building a plan that can be worked.', N'Plan around customer outcome, solution play, stakeholders, proof needs, demo or workshop sequence, and next decision.', N'Which solution pursuit needs a clearer plan? What proof or stakeholder coverage is missing?', N'Before the session: bring one live solution pursuit, solution play, lead list, opportunity, or investment case relevant to this huddle; confirm tool access; review last commitment and evidence.', N'What makes this solution pursuit worth SSP time? What next decision is the plan built to advance?', N'Listen for generic solution plans, missing stakeholder coverage, unclear proof path, and no 30-day plan.', N'Move from plan structure to one active pursuit.', N'If tooling is unavailable, sketch the plan on paper and capture evidence gaps.', N'Commit to to building or improving one solution-selling plan for a live pursuit.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Map who really decides on one pursuit, then reach the person missing from your list.', N'Bring the decision map and the absence that carried the most risk.'),
        (N'FG-SSP-VALUE', N'WF-X-VALUE-01', N'SSP-VALUE', N'Value needs to be created before the conversation, not after the objection. Today is about the customer-specific story.', N'The customer defines value. Use sourced evidence, caveats, use cases, and a clear next ask.', N'What customer priority does this solution map to? Which claim is supported, assumed, or missing evidence?', N'Before the session: bring one live solution pursuit, solution play, lead list, opportunity, or investment case relevant to this huddle; confirm tool access; review last commitment and evidence.', N'Which customer priority does the value narrative serve? Which claims are sourced?', N'Listen for generic value claims, unsupported ROI, customer priorities inferred rather than sourced, and missing caveats.', N'Move from value logic to the conversation or proof it supports.', N'If evidence sources are unavailable, build the narrative skeleton and list missing proof.', N'Commit to to one customer-specific value narrative with sourced evidence and caveats.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Test the assumptions behind one value claim, and remove any claim you cannot defend.', N'Bring the assumption table and the claim you dropped.'),
        (N'FG-SSP-CONV', N'WF-X-CONV-01', N'SSP-CONV', N'Preparation is the difference between explaining a solution and advancing a decision.', N'Prepare discovery questions, proof points, likely objections, role contributions, and a primary/fallback ask. Rehearse where useful.', N'What decision should this conversation advance? What objection is most likely? What proof will you use?', N'Before the session: bring one live solution pursuit, solution play, lead list, opportunity, or investment case relevant to this huddle; confirm tool access; review last commitment and evidence.', N'What is the intended decision from this meeting? What objection is most likely?', N'Listen for meetings framed around content rather than customer decision, objections first discovered live, and unclear ask.', N'Move from preparation to rehearsal or next customer ask.', N'If Agent J.ai is unavailable, role-play manually with one person acting as the customer.', N'Pick one upcoming solution conversation and prepares the brief or rehearsal.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Find the unknown that would change your recommendation, and ask about it in your next conversation.', N'Bring the question you asked and what the answer changed.'),
        (N'FG-SSP-ORCH', N'WF-X-ORCH-01', N'SSP-ORCH', N'Pursuits stall at handoffs. Today is about making every role, partner, funding dependency, and checkpoint explicit.', N'Name the objective, contributors, asks, owners, dates, dependencies, and escalation points.', N'Which handoff is currently assumed rather than owned? Where could partner or funding support change the path?', N'Before the session: bring one live solution pursuit, solution play, lead list, opportunity, or investment case relevant to this huddle; confirm tool access; review last commitment and evidence.', N'Which role, partner, or funding dependency is assumed but not owned?', N'Listen for unnamed owners, handoffs without dates, partner input treated as optional, and funding status overstated.', N'Move from orchestration principles to one stalled handoff.', N'If systems are unavailable, map the contributor chain and identify the break point.', N'Make one stalled contributor, partner, or funding handoff explicit.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Send one specific, dated ask to each role you need on a live pursuit.', N'Bring the asks you sent and which were accepted.'),
        (N'FG-SSP-COMP', N'WF-X-DEAL-01', N'SSP-COMP', N'Competitive response should be built on customer context and proof, not generic battlecards.', N'Use current approved competitive evidence, win/loss context, differentiators, objections, risks, and review flags.', N'Which competitor or alternative is shaping the decision? What proof is strongest and where is it weak?', N'Before the session: bring one live solution pursuit, solution play, lead list, opportunity, or investment case relevant to this huddle; confirm tool access; review last commitment and evidence.', N'Which competitive claim matters to the customer decision? What proof supports it?', N'Listen for stale battlecard claims, unsupported competitor statements, and differentiators not tied to customer priorities.', N'Move from competitor context to one proof-backed response plan.', N'If current sources are unavailable, separate what is known, assumed, and requiring Researcher/SME validation.', N'Build one proof-backed competitive response for a live pursuit.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Build one objection handler tied to approved proof, and use it in a live conversation.', N'Bring the handler, the objection it met, and whether the proof held.'),
        (N'FG-SSP-DEAL', N'WF-X-DEAL-01', N'SSP-DEAL', N'The final SSP huddle is about the next decision, not the whole deal.', N'Inspect milestone readiness, stakeholder gaps, proof, blockers, dependencies, partner/funding needs, and owners.', N'What is the pursuit actually waiting on? What evidence or owner will clear the next decision?', N'Before the session: bring one live solution pursuit, solution play, lead list, opportunity, or investment case relevant to this huddle; confirm tool access; review last commitment and evidence.', N'What is the opportunity’s next real decision? What evidence or owner will clear it?', N'Listen for close-date language instead of next decision, unowned blockers, missing proof, and unclear stakeholder gaps.', N'Move from readiness inspection to a 14- to 30-day action plan.', N'If Sales Agent/MSXI is unavailable, inspect from known opportunity context and log source gaps.', N'Name the next decision on one solution opportunity and who owns each blocker.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Design the one conversation that would clear the next decision on a stalled opportunity.', N'Bring the conversation you designed and the decision it produced.'),
        (N'FG-SE-ORIENT', N'WF-ORIENT-01', N'SE-ORIENT', N'This huddle sets the working contract for SE use of AI: faster assembly, stronger evidence checks, and explicit human accountability.', N'The huddle motion is workflow-led, not a tool demo.
AI can assemble briefs, options, responses, and reusable packages, but SEs keep technical judgment and customer commitments.
Each huddle ends with one small test on live or sanitized work.', N'Which part of your week is assembling information rather than deciding anything?
Where do you already use AI, and where have you avoided it?
What would you need to see before you trusted an AI-drafted technical output?', N'Before the session: confirm access to the tools named for this path, and come ready to describe the work you repeat most weeks. No prior AI experience is needed for this session.', N'Which technical work do you repeat every week without thinking of it as a workflow?
Which of those steps is assembling information rather than making a decision?
Where must the SE judgment stay human no matter how good the output gets?', N'Listen for unvoiced scepticism, access blockers stated as disinterest, the assumption that this is a tool rollout, and people who describe only their exceptional work rather than the work they repeat. The recurring, unglamorous tasks are the ones worth mapping.', N'Move from how the motion works to the recurring work each person will map with the discovery prompt this week.', N'If tool access is not confirmed, still run the discovery conversation and record access blockers separately from interest. The discovery prompt can be run in whichever tool the person already has.', N'Close by pointing the team to the resources for next week''s topic and to the workflow-discovery prompt below. Week 1 is for finding the recurring work worth automating.', N'Which part of your week had you never thought of as a workflow until now? What would have to be true before you trusted AI with it?', N'Run this in Microsoft 365 Copilot, Cowork, or Scout before the next huddle, then bring the result to the session:

"I am a Solution Engineer at Microsoft and I want to find the recurring work in my week that AI could take on.
1. First, look at my calendar, mail and Teams activity from the last four weeks and tell me what you can see about where my time actually goes. If you cannot access that data, say so and move to step 2 rather than guessing.
2. Then ask me up to five short questions, one at a time, to cover the work that never shows up in a calendar or an inbox.
3. Then list the five things I do most often. For each one give an estimate of the time it costs me per month, whether it is best handled as a saved prompt, a reusable skill, a scheduled automation or an existing agent, and the one judgment that must stay mine.
4. Rank them by time returned and tell me which one to start with."', N'Bring the ranked list of the five things you repeat most, which of them looked like a prompt, skill, automation, or agent fit, and any AI experience from the week, including anything that did not work.'),
        (N'FG-SE-CONV', N'WF-X-CONV-01', N'SE-CONV', N'Technical responses move faster when supported answers, assumptions, confidence, exceptions, and required reviewers are visible.', N'Answer with sources and confidence, not just fluency.
Preserve unsupported areas instead of smoothing them over.
Use the response package to route review, not to bypass it.', N'Which technical answer needs evidence before it can be used?
Where do we usually hide uncertainty?
Who must review the response before it goes to the customer?', N'Bring one RFP question, security or architecture questionnaire item, technical ask, or objection that requires a governed response.', N'Which answer is most consequential?
What source supports it?
Where should the response show confidence, caveat, exception, or SME-needed flag?', N'Listen for confident but unsourced answers, hidden uncertainty, overbroad commitments, and missing reviewers.', N'Move from answer drafting to response governance and exception routing.', N'If sources are not approved, create the exception list and reviewer path instead of drafting final language.', N'Commit to to one technical answer matrix or exception list with reviewer flags.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Prepare one technical conversation by finding the unknown that would change your recommendation.', N'Bring the unknown you found and the question you used to close it.'),
        (N'FG-SE-ARCH-1', N'WF-X-ARCH-01', N'SE-ARCH-1', N'Architecture validation works best when options, criteria, assumptions, and risks are visible before the technical debate starts.', N'Compare options against the agreed decision criteria.
Name the assumptions and validation steps, not just the recommended design.
Use AI to assemble evidence and decision records while keeping architecture judgment human.', N'Which architecture assumption would hurt most if wrong?
What criteria will decide between options?
What validation step should happen before the customer sees the recommendation?', N'Bring one architecture decision, relevant customer criteria, approved technical sources, and known constraints.', N'Which option should be compared, and against what criteria?
Which assumption needs validation first?
What would make the architecture recommendation unsafe to share?', N'Listen for unchallenged assumptions, uncited guidance, missing security or operations review, and options that are not tied to criteria.', N'Move from option comparison to creating the architecture decision record.', N'If authoritative sources are unavailable, identify required sources and reviewers before drafting.', N'Commit to to one architecture assumption or option you will validate against agreed criteria.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Design one solution and name the constraint that most limits it.', N'Bring the design and the constraint you validated.'),
        (N'FG-SE-ARCH-2', N'WF-X-ARCH-01', N'SE-ARCH-2', N'A demo or workshop should advance a customer decision, not tour a product. Today narrows the experience to proof that matters.', N'Anchor the experience in the customer scenario and decision.
Prepare evidence, objections, roles, environment needs, and fallback plan.
Do not rely on demo energy to cover unclear criteria.', N'What decision should the demo or workshop make easier?
Which scenario proves the most important customer concern?
Where could environment, permission, or data issues derail the experience?', N'Bring one demo, workshop, or technical customer session and the decision it needs to advance.', N'What decision should the demo or workshop advance?
Which scenario proves that decision?
What could fail because of data, tenant, permission, or environment constraints?', N'Listen for feature tours, unclear audience, unsupported claims, missing fallback plans, and proof not tied to criteria.', N'Move from scenario selection to the demo or workshop plan.', N'If the environment is unavailable, build the plan and mark environment validation as the human checkpoint.', N'Commit to to one demo or workshop plan tied to a specific customer decision.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Build one demo or workshop around the customer''s decision rather than the product''s features.', N'Bring what you cut and what the customer actually asked about.'),
        (N'FG-SE-ARCH-3', N'WF-X-ARCH-01', N'SE-ARCH-3', N'A PoC is valuable only if it has a bounded hypothesis, success criteria, and an exit decision before work starts.', N'Define the smallest useful proof.
Make success, exit, milestones, owners, dependencies, and review gates observable.
Pressure-test readiness before the customer or delivery team absorbs ambiguity.', N'What is the smallest proof that would answer the technical decision?
Which success criterion is too vague?
What should trigger exit, handoff, or no-go?', N'Bring one proposed PoC or proof motion, constraints, resources, dependencies, and desired technical decision.', N'What is the smallest useful proof?
Which success criterion is measurable?
Which dependency or owner is missing?', N'Listen for vague success criteria, PoCs that duplicate demo work, unowned dependencies, and no exit path.', N'Move from proof idea to readiness pressure test.', N'If customer data or resources are unavailable, use the missing dependency as the main readiness finding.', N'Commit to to one PoC scope revision that improves success criteria, dependencies, or exit path.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Scope one proof with success criteria and a stop condition agreed before it starts.', N'Bring the criteria, the stop condition, and who agreed to them.'),
        (N'FG-SE-DISC', N'WF-X-DISC-01', N'SE-DISC', N'Discovery should end with decision criteria, not a second discovery meeting. Today focuses on making the customer decision explicit early.', N'Start from the customer decision and work backward to criteria and evidence.
Separate sourced facts from hypotheses and open questions.
Capture what must be validated before architecture, demo, or PoC work begins.', N'Which decision is the customer actually trying to make?
What evidence gap would make the next technical step unsafe?
What criteria need to be agreed rather than inferred?', N'Bring one upcoming or recent technical discovery conversation, approved context, known constraints, and any open technical questions.', N'Which discovery question would most change the technical decision?
What evidence is missing or only assumed?
Which criteria must be agreed with the customer?', N'Listen for vague decisions, inferred criteria, missing evidence, and questions that sound impressive but do not advance the decision.', N'Move from discovery discussion to building the actual decision-criteria brief.', N'If tooling is unavailable, draft the criteria and evidence-gap structure manually.', N'Commit to to one discovery brief that includes decision criteria and evidence gaps.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Run one discovery conversation with the decision criteria written down before you go in.', N'Bring the criteria you took in and the one that turned out to be wrong.'),
        (N'FG-SE-HEALTH', N'WF-X-HEALTH-01', N'SE-HEALTH', N'Technical risk should be named while it is still a decision, not after it becomes a customer escalation.', N'Inspect exit criteria, blockers, proof gaps, objections, dependencies, and handoffs.
Every risk needs evidence, owner, mitigation, checkpoint, and next decision.
Use AI to surface signals, but use SE judgment to prioritize them.', N'What technical risk is blocking progression right now?
Which proof gap is being treated as if it were already closed?
Who owns the next technical action?', N'Bring one opportunity or technical workstream with a blocker, proof gap, objection, or dependency.', N'Which technical risk is blocking progression?
What evidence would clear or confirm it?
Who owns the mitigation and next checkpoint?', N'Listen for risks without owners, proof gaps treated as closed, delivery handoffs without requirements, and blockers framed too broadly.', N'Move from risk naming to action plan and handoff.', N'If opportunity context is unavailable, build the risk register from known facts and flag missing source context.', N'Name one technical risk, the evidence needed, the owner, and the next checkpoint.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Identify one technical risk early enough to be a conversation rather than an escalation.', N'Bring the risk, when you found it, and what you did about it.'),
        (N'FG-SE-ASSET', N'WF-X-ASSET-01', N'SE-ASSET', N'Reuse only works when an asset has enough context for someone else to trust and adapt it.', N'Package purpose, prerequisites, steps, parameters, validation checks, limitations, owner, and example use.
Remove sensitive content before reuse.
Use Skill Blueprints for repeatable workflows that are not validated assets yet.', N'What did you build recently that another SE will rebuild?
What context would make someone trust and adapt it?
What should not be reused without review?', N'Bring one demo, script, architecture, checklist, response, or pattern that could become reusable.', N'Which asset is worth reusing?
What context would make it usable by another SE?
What must be removed, validated, or tested before sharing?', N'Listen for assets without owner, missing prerequisites, sensitive content, unclear limitations, and reuse patterns that should become blueprints.', N'Move from asset selection to packaging or Skill Blueprint creation.', N'If the repository location is unclear, package the asset and record the placement decision as a blocker.', N'Package one reusable technical asset or drafts one Skill Blueprint.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Turn one piece of work you already did into something another SE could reuse.', N'Bring the asset and who you gave it to.'),
        (N'FG-CE-ORIENT', N'WF-ORIENT-01', N'CE-ORIENT', N'This is the session that explains the rest. Be honest about scepticism now rather than carrying it for eight weeks.', N'Huddles are 30 minutes and workflow-led, not tool demos.
Every session ends with one thing you will try.
Human judgment stays explicit at every step. That is the point, not a caveat.', N'Which part of your week is assembling information rather than deciding anything?
Where do you already use AI, and where have you avoided it?
What would you need to see before you trusted an AI-drafted commercial output?', N'Before the session: confirm access to the tools named for this path, and come ready to describe the work you repeat most weeks. No prior AI experience is needed for this session.', N'Which commercial work do you repeat every week without thinking of it as a workflow?
Which of those steps is assembling information rather than making a decision?
Where must the CE judgment stay human no matter how good the output gets?', N'Listen for unvoiced scepticism, access blockers stated as disinterest, the assumption that this is a tool rollout, and people who describe only their exceptional work rather than the work they repeat. The recurring, unglamorous tasks are the ones worth mapping.', N'Move from how the motion works to the recurring work each person will map with the discovery prompt this week.', N'If tool access is not confirmed, still run the discovery conversation and record access blockers separately from interest. The discovery prompt can be run in whichever tool the person already has.', N'Close by pointing the team to the resources for next week''s topic and to the workflow-discovery prompt below. Week 1 is for finding the recurring work worth automating.', N'Which part of your week had you never thought of as a workflow until now? What would have to be true before you trusted AI with it?', N'Run this in Microsoft 365 Copilot, Cowork, or Scout before the next huddle, then bring the result to the session:

"I am a Commercial Executive at Microsoft and I want to find the recurring work in my week that AI could take on.
1. First, look at my calendar, mail and Teams activity from the last four weeks and tell me what you can see about where my time actually goes. If you cannot access that data, say so and move to step 2 rather than guessing.
2. Then ask me up to five short questions, one at a time, to cover the work that never shows up in a calendar or an inbox.
3. Then list the five things I do most often. For each one give an estimate of the time it costs me per month, whether it is best handled as a saved prompt, a reusable skill, a scheduled automation or an existing agent, and the one judgment that must stay mine.
4. Rank them by time returned and tell me which one to start with."', N'Bring the ranked list of the five things you repeat most, which of them looked like a prompt, skill, automation, or agent fit, and any AI experience from the week, including anything that did not work.'),
        (N'FG-CE-HEALTH', N'WF-X-HEALTH-01', N'CE-HEALTH', N'Risk you find this week is a conversation. The same risk found by the customer is an escalation. Today is about finding it earlier.', N'A health score can tell you something is wrong. It rarely tells you what to do.
Every risk needs an owner and a date or it is an observation.
AI is good at surfacing signal. Prioritizing it is judgment.', N'Which account is at risk in a way the reporting does not show?
What stops a known risk from getting an owner?
Which part of this carries policy or precedent risk?', N'Before the session: confirm tool access for this huddle, bring one real commercial structure and policy example you are working on now, and review the commitment you made last week.', N'Which activity here is closest to what you are working on this week?
What would you need to see before you trusted the output?
Where would this break in your real commercial structure and policy work?', N'Through the lens of commercial structure and policy, listen for: risk described without an owner or a date; health reported by score rather than cause; and interventions discussed but never started.', N'Move from how risk surfaces to one account that is actually at risk now.', N'If status data is unavailable, work from what people know and note where the evidence should have come from.', N'Name one risk, one intervention and one owner.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Rank your commercial risks, then take the top one to its owner with a proposed intervention.', N'Bring the risk, the intervention, and the authoritative source behind it.'),
        (N'FG-CE-DEAL-1', N'WF-X-DEAL-01', N'CE-DEAL-1', N'Commercial structure decides whether a deal can move. Today is about comparing options before the structure hardens.', N'The goal is not to create an offer. The goal is to compare viable structures, surface trade-offs, and name the approval path while options still exist.', N'What option is the deal implicitly assuming? Which approval or exception would surprise the team later? What trade-off should be explicit before negotiation?', N'Before the session: bring one live opportunity, approved commercial context, known constraints, and the current approval or exception question.', N'Which commercial option is most plausible? What trade-off would change the decision? Where would this break if an approval requirement appears late?', N'Listen for: one default structure being treated as the only option; approval path ambiguity; pricing, term, or concession trade-offs not stated; and assumptions that need CE or Deal Desk review.', N'Move from possible structures to the smallest options matrix that makes the decision clearer.', N'If tooling is unavailable, build the options matrix manually and name the missing source evidence.', N'Create one commercial options matrix and names the approval path or missing evidence.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Build a commercial options matrix for one live deal and identify which option needs approval you do not hold.', N'Bring the options, the trade-offs, and the approval requirement you found.'),
        (N'FG-CE-DEAL-2', N'WF-X-DEAL-01', N'CE-DEAL-2', N'Reviewers do not need more history. They need the recommendation, options, assumptions, risks, and decision requested.', N'A commercial decision narrative should separate facts from judgment. It should show why this structure, what alternatives were considered, and who must review it.', N'What would a reviewer need to say yes, no, or not yet? Which assumption is unsupported? What customer impact needs to be explained plainly?', N'Before the session: bring a reviewed deal option, known assumptions, transition considerations, and the audience for the recommendation.', N'Which recommendation would a reviewer understand quickly? What assumption needs evidence? Which reviewer or decision owner is missing?', N'Listen for: narratives that bury the ask; options without trade-offs; customer impact omitted; and transition or migration risks stated without a source.', N'Move from deal facts to the internal recommendation and the decision being requested.', N'If tooling is unavailable, draft the decision narrative outline and identify the evidence gaps.', N'Draft one commercial decision narrative with options, assumption flags, and required reviewers.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Write the commercial recommendation for one deal in a form a reviewer could act on without asking you a question.', N'Bring the recommendation and the assumption a reviewer challenged.'),
        (N'FG-CE-DEAL-3', N'WF-X-DEAL-01', N'CE-DEAL-3', N'Negotiation is where vague structure becomes expensive. Today is about authority boundaries, give/get logic, and rehearsal before the customer asks.', N'The agent can help prepare scenarios and objections. The CE stays accountable for authority, customer commitments, concession discipline, and escalation triggers.', N'Where is your concession logic unclear? Which customer ask would trigger escalation? What must not be said before review?', N'Before the session: bring one negotiation scenario, approved position, authority boundaries, and any known customer asks.', N'Which customer ask would test your authority boundary? What give/get logic is clear enough to use? What must be reviewed before customer-facing use?', N'Listen for: concession logic that is not tied to value; authority boundaries not explicit; likely objections unrehearsed; and customer commitments that require review.', N'Move from negotiation principles to one realistic customer objection and the reviewed response.', N'If role-play tooling is unavailable, rehearse manually using the approved negotiation plan.', N'Rehearse one negotiation scenario and identifies authority, concession, and review boundaries.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Prepare one negotiation with your concession boundaries and escalation triggers set before the conversation.', N'Bring the plan, what you would not concede, and what actually happened.'),
        (N'FG-CE-ORCH', N'WF-X-ORCH-01', N'CE-ORCH', N'Commercial execution stalls when owners, evidence, and approval handoffs are implied. Today is about making them explicit.', N'Execution is not just follow-up. It is approval routing, evidence readiness, exception handling, ownership, and escalation without overstating authority.', N'Which handoff is implicit today? What evidence is missing for the next approver? Where could ECIF, Deal Desk, finance, policy, or legal review be needed?', N'Before the session: bring one in-flight deal or investment dependency, its known approval stage, and the evidence or owner currently missing.', N'Which handoff or approval is the deal actually waiting on? What evidence is missing? Who owns the next decision, and what should not be represented as approved?', N'Listen for: approval status overstated; handoffs without owners; ECIF, finance, Deal Desk, legal, or policy dependencies hidden; and blockers described without the next governed action.', N'Move from the full execution path to the single blocker and owner that must be handled next.', N'Use a sanitized scenario. If systems are unavailable, map the route, owner, evidence, and next decision without inferring approval state.', N'Name one approval or execution blocker, its owner, evidence needed, and next governed action.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Map the approval path for one deal and confirm the first owner knows it is coming.', N'Bring the path, the owners, and the blocker you cleared.'),
        (N'FG-CE-RENEW', N'WF-X-RENEW-01', N'CE-RENEW', N'Renewal risk is visible before the renewal date if commercial structure, value evidence, and approval needs are inspected early.', N'A renewal is not only a date. It is a commercial strategy with structure, risk, expansion potential, concessions, and approval path.', N'Which renewal risk is already visible? What expansion is supported by evidence? What approval or structure question should not wait?', N'Before the session: bring one renewal, approved context, current structure, risk signal, and expansion or approval question.', N'Which activity here is closest to what you are working on this week?
What would you need to see before you trusted the output?
Where would this break in your real commercial structure and policy work?', N'Through the lens of commercial structure and policy, listen for: renewals treated as administrative; risk noticed inside the last quarter; and expansion pursued without evidence of realized value.', N'Move from renewal principles to one renewal actually on the horizon.', N'If data is unavailable, work the renewal from what the team knows and note the evidence gaps.', N'Name one renewal risk, one supported expansion hypothesis, and the approval or structure question to resolve.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Build a renewal strategy for one account using real agreement and discount data, not recollection.', N'Bring the strategy, the data you retrieved, and the expansion you found or ruled out.'),
        (N'FG-CE-POLICY', N'WF-X-POLICY-01', N'CE-POLICY', N'Policy questions found at approval cost weeks. Today is about finding the question early and routing it to the authoritative owner.', N'AI can assemble the context and possible questions. It cannot interpret policy, approve exceptions, or invent authority. The useful output is a routed question with evidence, not a guessed answer.', N'Which policy or licensing question most often causes rework? Where did an approval path surprise you? Which interpretation must come from an authoritative source?', N'Before the session: bring one real commercial structure or policy example, the approved source you would check, and the decision or approval path currently unclear.', N'Which Practice helps you route the policy or licensing question fastest? What would you need to see before trusting the output? Where must the answer come from an authoritative owner instead of AI?', N'Through the lens of commercial structure and policy, listen for: policy interpreted from memory; uncertainty left unflagged; approval paths discovered late; and questions that need an authoritative owner rather than a generated answer.', N'Move from policy categories to one live deal question and the owner who can answer it.', N'If guidance is unavailable, list the questions, required evidence, and routing owner. Do not guess the answer.', N'Route one policy, licensing, or approval question to an authoritative owner with the evidence needed.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Take one open policy or licensing question to its authoritative owner rather than answering it yourself.', N'Bring the question, the owner, and the answer you received.'),
        (N'FG-CSA-ORIENT', N'WF-ORIENT-01', N'CSA-ORIENT', N'This is the session that explains the rest. Be honest about scepticism now rather than carrying it for eight weeks.', N'Huddles are 30 minutes and workflow-led, not tool demos.
Every session ends with one thing you will try.
Human judgment stays explicit at every step. That is the point, not a caveat.', N'Which part of your week is assembling information rather than deciding anything?
Where do you already use AI, and where have you avoided it?
What would you need to see before you trusted an AI-drafted architecture or delivery output?', N'Before the session: confirm access to the tools named for this path, and come ready to describe the work you repeat most weeks. No prior AI experience is needed for this session.', N'Which architecture or delivery work do you repeat every week without thinking of it as a workflow?
Which of those steps is assembling information rather than making a decision?
Where must the CSA judgment stay human no matter how good the output gets?', N'Listen for unvoiced scepticism, access blockers stated as disinterest, the assumption that this is a tool rollout, and people who describe only their exceptional work rather than the work they repeat. The recurring, unglamorous tasks are the ones worth mapping.', N'Move from how the motion works to the recurring work each person will map with the discovery prompt this week.', N'If tool access is not confirmed, still run the discovery conversation and record access blockers separately from interest. The discovery prompt can be run in whichever tool the person already has.', N'Close by pointing the team to the resources for next week''s topic and to the workflow-discovery prompt below. Week 1 is for finding the recurring work worth automating.', N'Which part of your week had you never thought of as a workflow until now? What would have to be true before you trusted AI with it?', N'Run this in Microsoft 365 Copilot, Cowork, or Scout before the next huddle, then bring the result to the session:

"I am a Cloud Solution Architect at Microsoft and I want to find the recurring work in my week that AI could take on.
1. First, look at my calendar, mail and Teams activity from the last four weeks and tell me what you can see about where my time actually goes. If you cannot access that data, say so and move to step 2 rather than guessing.
2. Then ask me up to five short questions, one at a time, to cover the work that never shows up in a calendar or an inbox.
3. Then list the five things I do most often. For each one give an estimate of the time it costs me per month, whether it is best handled as a saved prompt, a reusable skill, a scheduled automation or an existing agent, and the one judgment that must stay mine.
4. Rank them by time returned and tell me which one to start with."', N'Bring the ranked list of the five things you repeat most, which of them looked like a prompt, skill, automation, or agent fit, and any AI experience from the week, including anything that did not work.'),
        (N'FG-CSA-PIPE', N'WF-X-PIPE-01', N'CSA-PIPE', N'Most of us have at some point defended a number we were not fully sure about. Today is about fixing the signal, not the spreadsheet.', N'A gap is usually three problems wearing one label: not enough, not moving, or dated wrong.
Certified data settles arguments opinion cannot.
Correction is judgment work. The agent proposes, you decide.', N'Where do consumption or usage signals become technical work for you?
Which shortfall signal is most likely to hide a technical cause?
What evidence would you need before owning an intervention?', N'Before the session: confirm access to the relevant certified report, bring one consumption or usage signal you are reviewing, and note what technical context the report does not show.', N'Which consumption or shortfall activity is closest to what you inspect today?
What would you need to verify before trusting the signal?
Where would this break if the report lacks architecture context?', N'Through the CSA lens, listen for: report signals separated from technical cause; assumptions about customer intent; missing owners; and interventions that require architecture or workload context.', N'Move from the report signal to one technical cause or blocker that can be validated this week.', N'If the data source is unavailable, map the current inspection routine and draft the prompt and human checkpoint for later testing.', N'Name one consumption signal you will validate and one technical question you will answer.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Name the technical cause behind one consumption gap, and start the intervention with an owner.', N'Bring the cause you identified and who owns the intervention.'),
        (N'FG-CSA-CONV', N'WF-X-CONV-01', N'CSA-CONV', N'Preparation is rarely the thing people disagree about. The problem is finding an hour for it. Today is about making it take ten.', N'A brief is not a summary. It is a position plus the questions that would change it.
The intended outcome is the part most preparation leaves out, and it changes how the meeting runs.
Anticipated objections are cheaper than recovered ones.', N'Which upcoming conversation needs a recommendation, not just a summary?
What evidence would make the advisory position credible?
What customer decision should the conversation advance?', N'Before the session: bring one upcoming technical advisory conversation, the intended decision, and the approved sources you would trust for preparation.', N'Which advisory conversation is worth preparing with AI support?
What evidence would you need before using the recommendation?
Where would the conversation fail if the ask is not clear?', N'Through the CSA lens, listen for: preparation that summarizes but does not decide; evidence gaps; customer facts needing review; and advisory recommendations without a named decision.', N'Move from generic preparation to one upcoming conversation and its intended customer decision.', N'If tooling is unavailable, build the brief structure for a real upcoming meeting and note where the evidence would come from.', N'Pick one upcoming advisory conversation and names the decision it should advance.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Prepare one advisory conversation around the decision you need, not the content you have.', N'Bring the recommendation, the evidence, and the decision you asked for.'),
        (N'FG-CSA-ARCH-1', N'WF-X-ARCH-01', N'CSA-ARCH-1', N'A design that has not been argued against has not really been validated. Today is about the proof, not the diagram.', N'Design and proof are one motion. A design the customer cannot see is a document.
Success criteria set before the work are the only ones that count.
AI accelerates the assembly. The architecture judgment stays human.', N'Which architecture option is still being treated as obvious?
What decision criteria would change the recommendation?
What evidence would you need before supporting this design?', N'Before the session: bring one architecture decision or design assumption, the known constraints, and the evidence you would use to compare options.', N'Which architecture option comparison is worth doing now?
What decision criteria must be explicit before recommending?
Where could current guidance conflict or lack evidence?', N'Through the CSA lens, listen for: untested assumptions; option comparisons without decision criteria; public guidance used without applicability review; and controls, governance, or resilience claims needing SME validation.', N'Move from architecture principles to one live architecture decision with explicit criteria.', N'If the environment is unavailable, define the validation approach and the success criteria on paper.', N'Name one architecture assumption or option you will compare against explicit criteria.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Draft one production-ready design and name the dependency most likely to break it.', N'Bring the design and the dependency you validated.'),
        (N'FG-CSA-ARCH-2', N'WF-X-ARCH-01', N'CSA-ARCH-2', N'A design that has not been argued against has not really been validated. Today is about the proof, not the diagram.', N'Design and proof are one motion. A design the customer cannot see is a document.
Success criteria set before the work are the only ones that count.
AI accelerates the assembly. The architecture judgment stays human.', N'Which dependency could make the design fail in production?
What proof is small enough to validate the decision?
Who owns the next technical decision after validation?', N'Before the session: bring one validation path, proof plan, or delivery-readiness question tied to a real workload or customer scenario.', N'Which validation or proof plan would reduce delivery risk fastest?
What dependency must be owned before committing the design?
Where does ECIF or delivery-readiness change the technical plan?', N'Through the CSA lens, listen for: validation scoped too broadly; unowned prerequisites; proof criteria written after work begins; and investment-funded scope that may not be deliverable as designed.', N'Move from the design to the smallest validation path that can change the decision.', N'If the environment is unavailable, define the validation approach and the success criteria on paper.', N'Name one validation or delivery-readiness dependency you will make explicit.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Define the validation path for one design, including what would tell you to stop.', N'Bring the validation path and the stop condition you set.'),
        (N'FG-CSA-HEALTH', N'WF-X-HEALTH-01', N'CSA-HEALTH', N'Risk you find this week is a conversation. The same risk found by the customer is an escalation. Today is about finding it earlier.', N'A health score can tell you something is wrong. It rarely tells you what to do.
Every risk needs an owner and a date or it is an observation.
AI is good at surfacing signal. Prioritizing it is judgment.', N'Which technical risk is visible now but not yet owned?
What is evidence, and what is interpretation?
What intervention could prevent this from becoming customer-visible?', N'Before the session: bring one technical health signal, risk, or dependency you are tracking, plus the source you would use to validate it.', N'Which technical health activity is closest to a real account risk?
What evidence separates the risk from a hunch?
Who owns the intervention if the risk is real?', N'Through the CSA lens, listen for: health scores treated as causes; risks without owners or dates; technical blockers becoming customer-visible; and actions that require CSAM, support, delivery, or commercial alignment.', N'Move from health signal to one risk, its evidence, owner, and next intervention.', N'If status data is unavailable, work from what people know and note where the evidence should have come from.', N'Name one technical risk, its evidence, its owner, and the next intervention.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Find one technical health risk that is not visible in the data, and take it to its owner.', N'Bring the risk, where the signal came from, and who now owns it.'),
        (N'FG-CSA-VALUE-1', N'WF-X-VALUE-01', N'CSA-VALUE-1', N'Value without evidence tends to read as opinion. Today is about the evidence, and who needs to hear it.', N'The customer defines value. Our job is to evidence it in their terms.
Causality is easy to claim and hard to support. Say what the data supports.
A value story nobody hears is not value realized.', N'Which technical progress has not yet been translated into customer value?
Which cost, consumption, or optimization signal is credible enough to use?
What claim would you refuse to make without stronger evidence?', N'Before the session: bring one optimization, consumption, or delivery-progress signal and the outcome it might support.', N'Which optimization or progress signal could become a value story?
What financial or technical claim requires review?
What evidence is missing before recommending action?', N'Through the CSA lens, listen for: invented savings; correlation presented as causality; optimization divorced from architecture tradeoffs; and value claims not tied to supported outcomes.', N'Move from the signal to one bounded recommendation or technical value narrative.', N'If evidence sources are unavailable, build the value structure and identify what evidence you would need.', N'Commit to to one evidence-backed optimization or technical value recommendation.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Evidence one technical outcome in terms the customer would use themselves.', N'Bring the outcome, the evidence, and how you phrased it.'),
        (N'FG-CSA-VALUE-2', N'WF-X-VALUE-01', N'CSA-VALUE-2', N'Value without evidence tends to read as opinion. Today is about the evidence, and who needs to hear it.', N'The customer defines value. Our job is to evidence it in their terms.
Causality is easy to claim and hard to support. Say what the data supports.
A value story nobody hears is not value realized.', N'What value story would the customer actually recognize?
Which evidence supports the story, and which part is still only expected?
What next technical action would make the value more real?', N'Before the session: bring one technical review, business review, or value-realization example and the evidence behind it.', N'Which customer review package would benefit from AI assembly?
What evidence must travel with the value story?
Which next technical action makes the value more credible?', N'Through the CSA lens, listen for: progress not connected to agreed outcomes; unsupported realization claims; missing source links; and follow-through that lacks owners.', N'Move from value language to the evidence package and next technical action.', N'If evidence sources are unavailable, build the value structure and identify what evidence you would need.', N'Commit to to one technical value story and the evidence that will travel with it.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Produce one costed optimization recommendation the customer could act on this quarter.', N'Bring the recommendation, the cost basis, and the customer response.'),
        (N'FG-CSAM-ORIENT', N'WF-ORIENT-01', N'CSAM-ORIENT', N'This is the session that explains the motion through the CSAM lens: less status assembly, more customer outcome leadership.', N'Huddles are 30 minutes and workflow-led. CSAM work stays human-led: AI helps gather, synthesize, draft and monitor; the CSAM validates context, trust, commitments and customer-facing messages.', N'Which part of your week is assembling information rather than deciding anything?
Where do you already use AI, and where have you avoided it?
What would you need to see before you trusted an AI-drafted customer success output?', N'Before the session: confirm access to the tools named for this path, and come ready to describe the work you repeat most weeks. No prior AI experience is needed for this session.', N'Which customer success work do you repeat every week without thinking of it as a workflow?
Which of those steps is assembling information rather than making a decision?
Where must the CSAM judgment stay human no matter how good the output gets?', N'Listen for unvoiced scepticism, access blockers stated as disinterest, the assumption that this is a tool rollout, and people who describe only their exceptional work rather than the work they repeat. The recurring, unglamorous tasks are the ones worth mapping.', N'Move from how the motion works to the recurring work each person will map with the discovery prompt this week.', N'If tool access is not confirmed, still run the discovery conversation and record access blockers separately from interest. The discovery prompt can be run in whichever tool the person already has.', N'Close by pointing the team to the resources for next week''s topic and to the workflow-discovery prompt below. Week 1 is for finding the recurring work worth automating.', N'Which part of your week had you never thought of as a workflow until now? What would have to be true before you trusted AI with it?', N'Run this in Microsoft 365 Copilot, Cowork, or Scout before the next huddle, then bring the result to the session:

"I am a Customer Success Account Manager at Microsoft and I want to find the recurring work in my week that AI could take on.
1. First, look at my calendar, mail and Teams activity from the last four weeks and tell me what you can see about where my time actually goes. If you cannot access that data, say so and move to step 2 rather than guessing.
2. Then ask me up to five short questions, one at a time, to cover the work that never shows up in a calendar or an inbox.
3. Then list the five things I do most often. For each one give an estimate of the time it costs me per month, whether it is best handled as a saved prompt, a reusable skill, a scheduled automation or an existing agent, and the one judgment that must stay mine.
4. Rank them by time returned and tell me which one to start with."', N'Bring the ranked list of the five things you repeat most, which of them looked like a prompt, skill, automation, or agent fit, and any AI experience from the week, including anything that did not work.'),
        (N'FG-CSAM-SPLAN', N'WF-X-PLAN-01', N'CSAM-SPLAN', N'Success planning is not documentation. It is how the customer and Microsoft agree what progress means.', N'A plan should name outcomes, milestones, owners, risks and review points. AI can draft and inspect the plan, but only the CSAM can validate the customer priority and commitment.', N'When did your success plan last change because the customer''s priorities changed?
Which milestone in it would the customer not recognize as theirs?
What is in the plan because it is genuinely the outcome, and what is there because it was easy to measure?', N'Before the session: bring one active customer priority, its current CSP or success-plan notes and the latest review or action list.', N'Which outcome in your plan is stated in the customer''s words rather than ours?
Which milestone has drifted without anyone deciding to move it?
What would you remove from the plan today to make it governable?', N'Listen for plans built around Microsoft milestones rather than customer outcomes, measures chosen because they are available rather than meaningful, owners who have never agreed to their commitment, and plans so long that nobody governs them. Also listen for drift being reported rather than decided.', N'Move from the plan as it stands to the single outcome you will make observable this week.', N'If the tool or data source is unavailable, map the current workflow manually, name the trusted sources and draft the prompt plus human checkpoint for later testing.', N'Name the customer, the one outcome you will make observable this week, and what you will remove from the plan to keep it governable.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Make one success plan outcome observable this week, and remove something to keep the plan governable.', N'Bring the outcome you made measurable and what you removed.'),
        (N'FG-CSAM-HEALTH', N'WF-X-HEALTH-01', N'CSAM-HEALTH', N'Today is about moving from signal review to intervention. Scores help, but action changes the customer trajectory.', N'Health work spans adoption, usage, support, delivery, sentiment and stakeholder change. The CSAM must separate noise from the risk that matters most right now.', N'Which customer worries you for reasons the health score does not capture?
What did someone say in a recent conversation that has not made it into any system?
Which risk have you been watching rather than acting on, and why?', N'Before the session: bring one account with visible health, adoption, support or delivery risk and the current owner or open question.', N'What is the driver behind the score, not the score itself?
Which signal came from a person rather than a system, and did it survive into the record?
Who owns the intervention, and by when does it have to start to matter?', N'Listen for health scores treated as the diagnosis rather than the symptom, risks the team has normalized, interventions without owners, and conversation-based signals that never reached the data. Also listen for the customer''s own view of their health being absent from the discussion.', N'Move from the ranked health view to one intervention with an owner, a due date, and an escalation threshold.', N'If the tool or data source is unavailable, map the current workflow manually, name the trusted sources and draft the prompt plus human checkpoint for later testing.', N'Name the top risk, its actual driver rather than its score, the owner who has agreed to the intervention, and the escalation threshold.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Find the driver behind one health score, then take the intervention to an owner who agrees to it.', N'Bring the driver, the owner, and the escalation threshold you set.'),
        (N'FG-CSAM-EXEC', N'WF-X-CONV-01', N'CSAM-EXEC', N'Executive alignment is where customer success becomes visible to the people who can sponsor, unblock or redirect it.', N'Stakeholder maps should show influence, decision rights, relationship health and the next ask. AI can assemble signals; the CSAM decides the message and timing.', N'Who is the most senior person at this customer you have never spoken to directly?
Which stakeholder could stop this work, and do you know what they care about?
When an executive last engaged, what did they actually want from us?', N'Before the session: bring one upcoming executive or sponsor conversation and the latest stakeholder context.', N'Which stakeholder can stop this, and what do they need to believe?
Where is your coverage a title on a map rather than a relationship?
What would you ask the executive for if you had fifteen minutes tomorrow?', N'Listen for stakeholder maps built from org charts rather than observed behavior, executive relationships that exist only through an intermediary, engagement plans with no ask, and blockers identified without a plan to reach them. Also listen for assuming a quiet stakeholder is a supportive one.', N'Move from the stakeholder map to the one relationship you will build this month and the reason they would take the meeting.', N'If the tool or data source is unavailable, map the current workflow manually, name the trusted sources and draft the prompt plus human checkpoint for later testing.', N'Name the stakeholder you will reach this month, what that person needs to believe, and who can make the introduction.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Reach one stakeholder you have never spoken to directly, and know what they care about before you do.', N'Bring who you reached, how, and what you learned that you did not expect.'),
        (N'FG-CSAM-ORCH', N'WF-X-ORCH-01', N'CSAM-ORCH', N'CSAM orchestration is making the customer-success system observable enough to run.', N'Handoffs need an input, owner and date. Escalation is not a failure when it is used to unblock the system and protect customer outcomes.', N'Where does work currently stop between Microsoft, the partner, and the customer?
Who believes they own something that someone else also believes they own?
Which handoff have you personally been compensating for?', N'Before the session: bring one workstream involving Microsoft, customer, partner, support or delivery handoffs.', N'Where exactly does work stop between the three parties?
Who thinks they own that step, and have you asked them?
What are you personally absorbing because the handoff does not work?', N'Listen for the CSAM compensating for a broken handoff rather than fixing it, ownership assumed across company boundaries, partner commitments with no date, and coordination meetings that report rather than decide. Also listen for the customer''s own team being left out of the orchestration picture.', N'Move from the coordination map to the one handoff you will make explicit, with both sides named.', N'If the tool or data source is unavailable, map the current workflow manually, name the trusted sources and draft the prompt plus human checkpoint for later testing.', N'Name the handoff you will make explicit, both parties by name, and the date it will be agreed rather than assumed.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Make one handoff explicit this week by agreeing it with both sides rather than assuming it.', N'Bring the handoff, both owners, and the date it was agreed.'),
        (N'FG-CSAM-VALUE', N'WF-X-VALUE-01', N'CSAM-VALUE', N'Adoption activity does not automatically become customer value. Today is about proving and accelerating value realization.', N'Adoption plans should link underused features, customer priorities, behavior-change actions, milestones and value evidence. AI can draft the plan and value narrative; the CSAM validates truth and relevance.', N'What value has this customer actually realized that you could prove today?
Where is adoption stalled, and do you know why or are you guessing?
What would the customer say they got, if asked without us in the room?', N'Before the session: bring one workload or solution where adoption progress, friction or value proof needs to be clarified.', N'What value can you evidence today, and what are you asserting?
Where adoption stalled, do you know the cause or are you inferring it?
Would the customer describe the value the same way you just did?', N'Listen for value claimed from usage figures alone, adoption barriers guessed rather than investigated, realized value described in Microsoft terms rather than customer outcomes, and proof that would not survive a procurement conversation. Also listen for value stories that have never been said back to the customer.', N'Move from the value picture to one claim you will evidence, and one adoption barrier you will actually diagnose.', N'If the tool or data source is unavailable, map the current workflow manually, name the trusted sources and draft the prompt plus human checkpoint for later testing.', N'Name one value claim you will evidence, one adoption barrier you will diagnose rather than guess at, and how you will say it back to the customer.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Evidence one value claim, and diagnose one adoption barrier instead of guessing at it.', N'Bring the evidenced claim and what you found was actually blocking adoption.'),
        (N'FG-CSAM-RENEW', N'WF-X-RENEW-01', N'CSAM-RENEW', N'Renewal readiness starts before the renewal motion. Today is about seeing risk and growth conditions early.', N'Consumption, MACC or usage trajectory, adoption gaps, value evidence, support health and stakeholder signals all shape renewal confidence.', N'Which renewal are you least confident about, and what specifically drives that?
What consumption signal would you want to see six months before a renewal conversation?
Where is growth genuinely available versus where are you hoping?', N'Before the session: bring one account with renewal, consumption, usage or expansion relevance in the near planning horizon.', N'What is your forecast based on, and how far ahead does the signal reach?
Which growth opportunity is supported by consumption evidence?
What would you need to know now to avoid a surprise at renewal?', N'Listen for forecasts driven by relationship confidence rather than consumption evidence, growth assumed from headroom rather than intent, renewal risk surfacing late because nobody looked early, and commercial ownership blurring between CSAM and CE. Also listen for consumption trends read without seasonality.', N'Move from the forecast to the one early signal you will start tracking, and who you will align it with.', N'If the tool or data source is unavailable, map the current workflow manually, name the trusted sources and draft the prompt plus human checkpoint for later testing.', N'Name the renewal you are least confident about, the early signal you will start tracking, and who you will align the forecast with.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Start tracking one early consumption signal and hand it to the account owner.', N'Bring the signal, why it matters, and who you handed it to.'),
        (N'FG-CSAM-ESCALATE', N'WF-X-HEALTH-01', N'CSAM-ESCALATE', N'Escalations test trust. Today is about moving from scattered status to a grounded recovery plan.', N'A useful brief names customer impact, current status, owner, decision needed, next action and update cadence. AI can consolidate threads; the CSAM validates tone, accuracy and accountability.', N'What issue are you currently managing that should probably already be escalated?
What is holding you back: evidence, ownership, or the conversation itself?
When an escalation last worked well, what made it work?', N'Before the session: bring one live or recent delivery risk, incident, support issue or overdue commitment.', N'What threshold would have told you to escalate this a month ago?
What does the recovery plan commit us to, and can we deliver it?
What will you tell the customer, and when?', N'Listen for escalation delayed to avoid an uncomfortable conversation, recovery plans that promise more than delivery can support, customer communication planned after the internal fix rather than alongside it, and escalations raised without a defined exit. Also listen for the same issue recurring without anyone treating the pattern.', N'Move from the delivery risk to a recovery plan with an owner, a customer message, and a defined exit condition.', N'If the tool or data source is unavailable, map the current workflow manually, name the trusted sources and draft the prompt plus human checkpoint for later testing.', N'Name the risk you will escalate or resolve this week, the recovery commitment delivery can actually support, and what the customer will be told.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Take one issue to escalation or resolution this week, with a recovery commitment delivery can actually support.', N'Bring the issue, the recovery plan, and what the customer was told.'),
        (N'FG-AE-INVEST', N'WF-INVEST-01', N'AE-INVEST', N'Investment should be connected to a real customer barrier, not added as a side process. Today is about the AE’s role in naming the investment hypothesis and routing the next decision.', N'Eligibility, funding, and approval are governed human decisions. AI may help assemble context, status, and evidence, but the AE should not overstate approval or commitment.', N'Where could investment remove a barrier? Which part is yours to advance? Who owns the next governed decision?', N'Before the session: bring one live opportunity or account barrier where investment may be relevant, plus any approved context you can safely use.', N'Where might investment remove a real barrier? What evidence supports that barrier? Who owns eligibility, funding, approval, delivery, or value proof?', N'Listen for funding implied as approved, hidden open questions, unowned handoffs, and investment ideas not tied to an account priority or decision.', N'Move from investment concept to the AE’s next governed action on one live case.', N'Use a sanitized scenario if live data is not appropriate. Do not infer eligibility, approval, or funding status.', N'Name the investment hypothesis, evidence gap, and next governed owner.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Test whether investment could remove one real barrier, then route the next decision without implying approval.', N'Bring the investment hypothesis, source evidence, open questions, owner, and the next governed action.'),
        (N'FG-AE-ORCH', N'WF-X-ORCH-01', N'AE-ORCH', N'AE orchestration works when everyone knows the customer decision, their role, the handoff, and the date. Today is about making that operating model explicit.', N'AEs often lead through influence without direct authority. AI can assemble commitments, role gaps, partner context, and follow-up drafts; the AE decides who to pull in and how to lead the motion.', N'Where is the handoff currently vague? Which role or partner is missing? What would reduce follow-up noise this week?', N'Before the session: bring one live account or opportunity that depends on multiple Microsoft roles, partners, or delivery handoffs.', N'Which role, partner, or handoff is missing right now? What input does each owner need? What follow-up should be automated or drafted, and what should remain relationship-led?', N'Listen for responsibility without authority, handoffs assumed rather than confirmed, partner motions added late, and meetings where every role attends but no owner is clear.', N'Move from role discussion to an owner/date/input map for one opportunity.', N'If systems are unavailable, map the handoff chain manually and capture the prompt or workflow to run later.', N'Name one handoff, role gap, or partner action you will make explicit this week.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Create or update one account-team operating brief with owners, inputs, dates, and next customer decision.', N'Bring the role/partner map, handoff list, follow-up message or plan, and what changed after owner validation.'),
        (N'FG-AE-VALUE', N'WF-X-VALUE-01', N'AE-VALUE', N'A QBR or executive cadence should not be a status meeting. It should make value, commitments, risks, and strategic asks visible enough for the customer to decide.', N'AI can assemble outcomes, usage signals, open commitments, risks, investments, and expansion plays. The AE validates what the customer would recognize as value and which ask advances the relationship.', N'What value has been delivered but not evidenced? Which customer commitment is still open? What strategic ask should the QBR create?', N'Before the session: bring one account with a QBR, SBR, renewal, or executive follow-up where value evidence matters.', N'What value would the customer recognize? Which outcome is supported by evidence, and which is only expected? What strategic ask should follow from the value story?', N'Listen for value claims without evidence, QBRs that become status readouts, unsupported causality, missing customer commitments, and expansion asks not tied to outcomes.', N'Move from value evidence to the executive brief or QBR ask the AE would actually use.', N'If evidence sources are unavailable, build the value structure and mark each claim as supported, assumed, or needs review.', N'Name one value claim to evidence and one strategic ask to sharpen.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Build one executive value or QBR brief and validate which claims are supported before sharing.', N'Bring the value/QBR brief, source evidence, unsupported claims removed, strategic asks, and owner for follow-up.'),
        (N'FG-ATS-INVEST', N'WF-INVEST-01', N'ATS-INVEST', N'Today is about assess the strategic and technical case for investment without turning the huddle into a tool demo or a status review.', N'The goal is A strategic and technical investment assessment with dependencies, readiness, risks, and the next governed decision named. AI can assemble evidence and draft options, but ATS judgment stays accountable for strategy, technical accuracy, and next decisions.', N'What technical problem is this investment actually meant to solve?
What would tell you six months from now that it worked?
Which dependency would quietly sink it, and who owns that dependency?', N'Before the session: confirm access to the named tools, bring one real account or technical strategy example, and review the commitment from the prior huddle.', N'What technical outcome does this investment buy that we could not get otherwise?
What is the observable measure that proves it worked?
Which approval or eligibility question are you assuming rather than confirming?', N'Listen for the ATS drifting into eligibility, funding, or approval decisions that belong to other owners, success measures that cannot be observed, deployment paths assumed rather than validated, and handoffs to delivery with no re-engagement trigger.', N'Move from the investment case to the technical evidence it needs and the governed decision that comes next.', N'If tooling is unavailable, map the workflow and human checkpoint manually, then draft the prompt for later testing.', N'Name the investment, the observable success measure, and the approval question you will route to its correct owner rather than answering themselves.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Test one investment case against its technical dependencies, and route one approval question to its real owner.', N'Bring the dependency that would sink it and the owner you routed the question to.'),
        (N'FG-ATS-CBR', N'WF-X-VALUE-01', N'ATS-CBR', N'Today is about prepare the technical contribution for a customer business review without turning the huddle into a tool demo or a status review.', N'The goal is A technical CBR contribution with roadmap points, evidence, risks, decisions, and follow-through. AI can assemble evidence and draft options, but ATS judgment stays accountable for strategy, technical accuracy, and next decisions.', N'What technical progress can you evidence, rather than assert?
Where has progress been slower than the customer expected, and how will you say so?
What decision do you want the review to produce?', N'Before the session: confirm access to the named tools, bring one real account or technical strategy example, and review the commitment from the prior huddle.', N'Which technical claim in your contribution can you evidence today?
How will you present the area where progress was slower than promised?
What decision should this review produce, and who makes it?', N'Listen for progress narrated rather than evidenced, slow areas omitted rather than addressed, roadmap statements that commit the product group, and reviews that end without a decision. Also listen for a technical contribution disconnected from the business outcome the customer cares about.', N'Move from the technical contribution to the decisions it should trigger, and the evidence each decision requires.', N'If tooling is unavailable, map the workflow and human checkpoint manually, then draft the prompt for later testing.', N'Name the technical claim you will evidence before the review, and the slow area you will address openly rather than omit.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Evidence one technical claim before your next customer review, and decide how you will address the slowest area.', N'Bring the evidenced claim and how you handled the area that is behind.'),
        (N'FG-ATS-HEALTH', N'WF-X-HEALTH-01', N'ATS-HEALTH', N'Today is about assess technical health and prioritize risk response without turning the huddle into a tool demo or a status review.', N'The goal is A prioritized technical risk response with source signals, owner, intervention, and checkpoint. AI can assemble evidence and draft options, but ATS judgment stays accountable for strategy, technical accuracy, and next decisions.', N'Which technical risk have you known about for weeks without acting on?
What is stopping you: evidence, ownership, or the conversation itself?
Which risk would the customer say is most urgent, and does it match yours?', N'Before the session: confirm access to the named tools, bring one real account or technical strategy example, and review the commitment from the prior huddle.', N'Which risk is most likely to become an escalation, and what is the earliest signal?
Who owns the intervention, and have they agreed to it?
What would you tell the customer today if you had to raise this now?', N'Listen for risks ranked by score rather than by consequence, interventions with no named owner, escalation thresholds that were never defined, and risks the team has normalized because they have lived with them. Also listen for signals from conversations that never made it into the system data.', N'Move from the ranked risk view to one intervention with an owner, a date, and an escalation threshold.', N'If tooling is unavailable, map the workflow and human checkpoint manually, then draft the prompt for later testing.', N'Name the top technical risk, the intervention, the owner who has agreed to it, and the threshold that would trigger escalation.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Take one technical risk to its owner this week with the intervention and the escalation threshold.', N'Bring the risk, the owner who accepted it, and the threshold you agreed.'),
        (N'FG-SE-INVEST', N'WF-INVEST-01', N'SE-INVEST', N'Investment-funded proof work needs scope, success measures, failure-mode awareness, and handoff boundaries before execution begins.', N'SE owns the technical clarity, not eligibility, policy, commercial, or approval decisions.
Success measures must be observable.
Delivery handoff should state what is decided, what remains open, and when SE must be re-engaged.', N'What technical problem is the investment meant to prove or unblock?
Which success measure is observable enough?
What failure mode would make the investment underdeliver?', N'Bring a proposed investment-funded proof, workshop, PoC, or scoped engagement and the current technical assumptions.', N'Which technical scope boundary matters most?
Which success measure proves the investment helped?
What failure mode or handoff gap needs to be closed before review?', N'Listen for eligibility or approval decisions implied by the SE, vague proof measures, hidden open questions, and delivery handoffs without re-engagement triggers.', N'Move from investment idea to bounded technical proof package.', N'If live data is inappropriate, use a sanitized case and do not infer eligibility, funding, policy, or approval status.', N'Commit to to one scoped technical proof artifact, success measure, or delivery handoff update.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Define what one investment-funded proof must demonstrate, in measures someone else could verify.', N'Bring the success measures and the failure mode you named.'),
        (N'FG-CE-INVEST', N'WF-INVEST-01', N'CE-INVEST', N'Investment succeeds on role clarity, evidence, and clean handoffs. Today is about the commercial and policy link in that chain.', N'Eligibility, funding, exception, and approval remain human decisions. The CE contribution is to surface commercial and policy dependencies, cite authoritative guidance, and route questions to the right owner.', N'Which commercial dependency would slow this investment later? Which decision is genuinely yours? Which question must be routed to an authoritative owner?', N'Before the session: bring one proposed or in-flight investment, customer agreement context, current policy question, and the known owner or approver.', N'Which activity helps clarify the commercial or policy dependency? What would make the output safe to use? Where must a human owner decide?', N'Listen for: eligibility, funding, or approval implied rather than decided; exception ownership unclear; handoffs without named owners; and questions that need authoritative guidance.', N'Move from the investment lifecycle to the CE-owned dependency and the next governed action.', N'Use a sanitized scenario. Do not use live customer data or infer eligibility, approval, exception, or funding status.', N'Map one investment dependency to the authoritative question, owner, and next human decision.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Map the approval dependencies for one investment and find where it is actually waiting.', N'Bring the dependency map and the blocker you identified.'),
        (N'FG-CSA-INVEST', N'WF-INVEST-01', N'CSA-INVEST', N'Investment succeeds on role clarity, evidence and clean handoffs. Today is about your part of that chain.', N'Every role owns one link. The chain breaks at the handoff.
Eligibility, funding and approval are human decisions. AI assembles the evidence.
An investment request without named open questions hides them rather than resolving them.', N'Where could investment-funded scope become undeliverable?
Which prerequisite, dependency, or owner must be confirmed before delivery starts?
What technical outcome evidence will be needed later?', N'Before the session: bring one proposed or approved investment-funded scope, known technical dependencies, and the delivery checkpoints you would want confirmed.', N'Which investment activity is closest to your real delivery responsibility?
What status or milestone data must be verified before acting?
Where could handoff, prerequisite, or ownership failure become customer-visible?', N'Through the CSA lens, listen for: funding or approval inferred from summaries; delivery status not checked against the authoritative record; unowned prerequisites; and technical outcomes that cannot be measured later.', N'Move from the investment lifecycle to the CSA''s delivery-readiness or outcome-evidence action on a live or sanitized case.', N'Use a sanitized scenario. Do not use live customer data or infer eligibility, approval or funding status.', N'Name one investment delivery-readiness check or outcome-evidence action and its owner.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Validate delivery readiness for one investment and name the dependency most likely to slip.', N'Bring the readiness assessment and the dependency you flagged.'),
        (N'FG-CSAM-INVEST', N'WF-INVEST-01', N'CSAM-INVEST', N'Customer investment should be governed through the success plan, not treated as a separate administrative process.', N'Investment execution needs owners, milestones, handoffs, risk tracking and value evidence. The CSAM governs the operating rhythm and realization story.', N'Is the investment on this account connected to the success plan, or running beside it?
Who owns delivery, and when did you last confirm status with them rather than assume it?
What evidence would the realization review need that you do not have yet?', N'Before the session: bring one active or proposed customer investment, scope, milestone list or execution question.', N'How does this investment show up in the success plan?
Which delivery status did you confirm rather than assume?
What evidence will the realization review need, and who is producing it?', N'Listen for investment running as a parallel process rather than part of the success plan, delivery status inferred from silence, realization evidence identified only when the review is booked, and the CSAM answering eligibility or approval questions that belong elsewhere.', N'Move from the investment rhythm to the one checkpoint you will run this month and the evidence it produces.', N'If the tool or data source is unavailable, map the current workflow manually, name the trusted sources and draft the prompt plus human checkpoint for later testing.', N'Name the investment checkpoint you will run, the delivery status you will confirm rather than assume, and the realization evidence you will start collecting.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Run one investment checkpoint and confirm a delivery status rather than assuming it.', N'Bring the status you confirmed and how it differed from what you assumed.'),
        (N'FG-ATS-PARTNER', N'WF-X-ORCH-01', N'ATS-PARTNER', N'Today is about align partner and specialist support to technical priorities without turning the huddle into a tool demo or a status review.', N'The goal is A partner and specialist alignment plan with feature gaps, owners, timing, and next decision. AI can assemble evidence and draft options, but ATS judgment stays accountable for strategy, technical accuracy, and next decisions.', N'Where is technical feature the constraint, rather than time or priority?
When you last brought in a specialist, did it change the outcome?
What would a partner need from you to arrive useful rather than catching up?', N'Before the session: confirm access to the named tools, bring one real account or technical strategy example, and review the commitment from the prior huddle.', N'Is the gap feature, capacity, or clarity? They need different answers.
What exactly would you ask this partner or specialist to do?
What will you send them so they arrive useful rather than catching up?', N'Listen for support requested by habit rather than by need, asks vague enough that anyone could decline them politely, briefings promised verbally and never sent, and customer-sensitive detail heading to an external partner without a classification step.', N'Move from the feature gap to one specific, dated ask with the briefing that makes it answerable.', N'If tooling is unavailable, map the workflow and human checkpoint manually, then draft the prompt for later testing.', N'Name the feature gap, the specific ask you will send, who receives it, and whether that recipient is internal or external.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Write one specific partner or specialist ask and send the briefing that makes it answerable.', N'Bring the ask, the briefing, and whether the recipient was internal or external.'),
        (N'FG-SSP-INVEST', N'WF-INVEST-01', N'SSP-INVEST', N'Investment requests slow down when inputs, owners, or open questions are hidden. Today is about readiness.', N'Separate facts from assumptions. Name confirmed inputs, gaps, contributors, policy/process questions, and next governed action.', N'Which request input is missing? Who owns it? What should not be represented as approved?', N'Before the session: bring one live solution pursuit, solution play, lead list, opportunity, or investment case relevant to this huddle; confirm tool access; review last commitment and evidence.', N'What request input is missing? Who owns it? What decision must remain human?', N'Listen for eligibility or funding implied rather than confirmed, hidden open questions, and contributor inputs without owners.', N'Move from request readiness to next governed action.', N'Use a sanitized scenario if live investment data should not be used.', N'Name the next governed investment action, owner, and evidence needed.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'Check one investment request against what a complete submission needs before you submit it.', N'Bring what was missing and where the request sits now.'),
        (N'FG-ALL-USECASE', N'WF-X-USECASE-01', N'ALL-USECASE', N'This huddle has no pre-written workflow. The team chooses one, which means the value depends entirely on picking a workflow people actually run. Anchor the session in real work and trusted context before anyone opens a tool.', N'The workflow must be recurring, not a one-off.
Someone in the room must actually own it.
A specific recent example beats a general description.
If the team cannot name a real example, the workflow is too abstract to work on.', N'What workflow are we improving today?
What triggers it, and how often does it run?
What inputs, constraints, and approvals shape it?
Whose work is it, and who else depends on the output?', N'Bring one recurring workflow you personally run and one recent example of it, including what made that run harder than it needed to be.', N'Where in this workflow is effort or quality lost today?
What is the smallest step AI could assist, rather than the whole workflow?
What must a person verify before the output is used?
What would a one-week version of this experiment look like?', N'Listen for scope that is too broad to test in a week, inputs the person cannot actually access, an output nobody would notice if it were wrong, and enthusiasm for a tool without a workflow behind it. Also listen for the opposite problem: a step so small that automating it changes nothing.', N'Move from the friction people named to one specific assistable step, then from that step to a single bounded experiment with an owner.', N'If a tool or data source is unavailable, map the workflow on paper and design the experiment for later execution. Use a hypothetical process shape if needed, but do not invent business facts, customer detail, or system behavior.', N'Name the workflow you chose, the one step you will test, the human checkpoint you will keep, and the evidence you will bring back. If you cannot name an owner or a date, the experiment is not real yet; shrink it until it is.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'What will you test this week? State the input, the action, the output, who reviews it, and what would tell you to stop.', N'Bring the actual output from your experiment, whether it worked or not. A failed experiment with evidence is more useful to the group than a success without it.'),
        (N'FG-ALL-DEAL', N'WF-X-DEAL-01', N'ALL-DEAL', N'Deal making features live inside Sales Agent. There is no separate agent to select: when you ask Sales a deal-related question, those features answer. This session is not about learning to run deals. It is about being able to find deal facts for your own accounts, whatever your role, instead of waiting for someone to send them to you.', N'Deal Agent is a skill inside Sales Chat, reached by picking the Sales agent in Microsoft 365 Copilot. There is nothing separate to install or select.
Its primary motion is renewals, specifically EA and MCA-E. That is where it is strongest.
The trigger is specificity. A TPID, agreement number, or enrollment number returns real data; a vague account reference returns a generic answer.
Keep one chat thread per deal. Mixing several deals into one thread confuses the context and makes the history hard to audit.
Looking up deal facts is open to every role. Commercial decisions, approvals, and material amendments are not.', N'When did you last need agreement, licensing, or renewal information and have to ask someone for it?
How long did that take, and what did you do while waiting?
What have you assumed about a customer''s entitlements that you have never actually verified?', N'Bring one real account you work on, and if you have it, an agreement number, enrollment number, or TPID. If you do not have an identifier, bring the account name and we will find one in the session.', N'What did the lookup return that you did not already know?
What did you previously assume about this customer''s estate that turned out to be wrong or unverified?
Where does this stop being your call and become the deal owner''s?', N'Listen for vague prompts producing vague answers, which is the most common reason people conclude deal making does not work. Listen for a first response being treated as final on a complex deal, when the guidance is to re-run and verify against current data. Listen for several unrelated deals being worked in one chat thread. Listen for someone treating a retrieved figure as approved pricing or a commitment, or stepping past retrieval into structuring a deal that belongs to the AE or Commercial Executive. Also listen for the opposite: someone escalating a question they could now answer themselves.', N'Move from the lookup you ran to the single fact that changes how you would open your next conversation with that customer.', N'If Sales Agent access is unavailable or a lookup returns nothing, work from an account you know and list what you would need to verify before the next customer conversation, then name who currently holds each answer. Do not guess at entitlements, pricing, or discount levels.', N'Name the account you looked up, the one fact that surprised you, and one question you previously would have escalated but can now answer yourself. If nothing was new, pick a less familiar account before the next session.', N'What did you learn today? Name one thing AI made easier, one thing that still needed your judgment, and one thing you would do differently next time.', N'What will you do this week? Look up one account before a real customer conversation and use one retrieved fact in that conversation.', N'Bring the prompt you used, what came back, and whether it changed how the conversation went. If the lookup returned nothing useful, bring the prompt so the group can sharpen it.')
    ) v([ExternalId], [TopicExternalId], [PlacementExternalId], [SessionIntroduction], [KeyTalkingPoints], [DiscussionQuestions], [PreparationChecklist], [FacilitatorQuestions], [ListenFor], [SuggestedTransitions], [FallbackGuidance], [WrapUpGuidance], [ReflectPrompt], [CommitPrompt], [BringBackEvidence])
)
SELECT @unresolved = 70 - COUNT(*) FROM raw
    INNER JOIN dbo.HuddleTopics AS t ON t.[ExternalId] = raw.[TopicExternalId]
    INNER JOIN dbo.HuddlePlacements AS p ON p.[ExternalId] = raw.[PlacementExternalId];
IF @unresolved <> 0
    THROW 51000, 'HuddleFacilitatorGuides: 70 source rows were expected to resolve their foreign keys but some did not. Run the earlier scripts in order and re-check the workbook.', 1;

COMMIT TRANSACTION;
GO
